INSERT INTO `abouts` (`id`, `aboutMe`, `aboutMeAz`, `created_at`, `updated_at`) VALUES
(1, 'Hello, I’m a web-developer, based on Baku. I have rich experience in web site design & building and customization.I am good at PHP,LARAVEL,MySQL,Javascript, jQuery, Ajax,HTML5,CSS3', 'Salam, Mən veb-proqramçıyam. Veb səhifələrin dizayn edilməsi, qurulması və düzəlişlər edilməsində zəngin təcrübə var. PHP,LARAVEL,MySQL,Javascript, jQuery, Ajax,HTML5,CSS3 texnologiyalarını bilirəm', '2021-03-01 20:42:14', '2021-03-01 20:47:00');
INSERT INTO `blogs` (`id`, `titleEn`, `titleAz`, `slugEn`, `slugAz`, `blogEn`, `blogAz`, `category_id`, `view`, `created_at`, `updated_at`) VALUES
(1, 'A program that calculates how many words are in a given text. Ready functions (explode, etc.) cannot be used', 'Verilmiş textdə neçə sözün olduğunu hesablayan proqram. Hazır funksiyalardan ( explode və s. ) istifadə etmək olmaz', 'a-program-that-calculates-how-many-words-are-in-a-given-text-ready-functions-explode-etc-cannot-be-used', 'verilmis-textde-nece-sozun-oldugunu-hesablayan-proqram-hazir-funksiyalardan-explode-ve-s-istifade-etmek-olmaz', '<pre>\n<code class=\"language-php\">&lt;?php\n/**\n * 1) A program that calculates how many words are in a given text. Ready functions (explode, etc.) cannot be used \n */\n\nfunction wordCounter ( $text = NULL )\n{\n	$spaceCounter = 0;\n	$word         = \'\';\n	$loop         = TRUE;\n	$n            = 0;\n	while ( $loop === TRUE )\n	{\n		if ( isset( $text[ $n ] ) )\n		{\n			if ( $text[ $n ] == \' \' )\n			{\n				$spaceCounter++;\n				$word = \'\';\n			}\n			$word .= $text[ $n ];\n			$n++;\n		}\n		else\n		{\n			$loop = FALSE;\n		}\n	}\n	$wordCounter = $spaceCounter + 1;\n\n	if ( $n === 0 )\n	{\n		return \'Please include a word\';\n	}\n\n	return $wordCounter;\n}\n\n$text = \'There are exactly eight words in this sentence.\';\necho wordCounter( $text );\n\n\n</code></pre>\n\n<p>//Output</p>\n\n<p>8</p>', '<pre>\n<code class=\"language-php\">&lt;?php\n/**\n * 1) Verilmiş textdə neçə sözün olduğunu hesablayan proqram. Hazır funksiyalardan ( explode və s. ) istifadə *etmək olmaz.\n */\n\nfunction wordCounter ( $text = NULL )\n{\n	$spaceCounter = 0;\n	$word         = \'\';\n	$loop         = TRUE;\n	$n            = 0;\n	while ( $loop === TRUE )\n	{\n		if ( isset( $text[ $n ] ) )\n		{\n			if ( $text[ $n ] == \' \' )\n			{\n				$spaceCounter++;\n				$word = \'\';\n			}\n			$word .= $text[ $n ];\n			$n++;\n		}\n		else\n		{\n			$loop = FALSE;\n		}\n	}\n	$wordCounter = $spaceCounter + 1;\n\n	if ( $n === 0 )\n	{\n		return \'Please include a word\';\n	}\n\n	return $wordCounter;\n}\n\n$text = \'Bu cumlede tami-tamina alti soz var\';\necho wordCounter( $text );\n\n\n</code></pre>\n\n<p>//Output</p>\n\n<p>6</p>', 8, 0, '2021-03-02 02:01:38', '2021-03-02 02:01:38'),
(2, 'A program that capitalizes the first letter of a sentence in a given text. You can\'t use explode.', 'Verilmiş textdəki cümlələrin ilk hərfini böyüklə yazan proqram. Hazır funksiyalardan ( explode ) istifadə etmək olmaz.', 'a-program-that-capitalizes-the-first-letter-of-a-sentence-in-a-given-text-you-cant-use-explode', 'verilmis-textdeki-cumlelerin-ilk-herfini-boyukle-yazan-proqram-hazir-funksiyalardan-explode-istifade-etmek-olmaz', '<pre>\n<code class=\"language-php\">&lt;?php\n/**\n * Verilmiş textdəki cümlələrin ilk hərfini böyüklə yazan proqram. Hazır funksiyalardan ( explode ) istifadə etmək olmaz.\n *\n * $text = \' Writing image code doesn\'t always mean better. should also pay attention to the smoothness and optimality of the helminth \';\n *\n */\n\nfunction uppercase ( $text = NULL )\n{\n	$loop      = TRUE;\n	$n         = 0;\n	$sentence  = \'\';\n	$uppercase = FALSE;//We need this to take into account the gaps at the beginning or after the sentence \n	while ( $loop === TRUE )\n	{\n		if ( isset( $text[ $n ] ) )\n		{\n			if ( $n === 0 )\n			{\n				$uppercase = TRUE;\n			}\n			else\n			{\n				if ( $text[ $n - 1 ] == \'.\' )\n				{\n					$uppercase = TRUE;\n\n				}\n			}\n\n			if ( $uppercase === TRUE &amp;&amp; $text[ $n ] != \' \' )\n			{\n				$sentence  .= strtoupper( $text[ $n ] );\n				$uppercase = FALSE;\n			}\n			else\n			{\n				$sentence .= $text[ $n ];\n			}\n\n			$n++;\n		}\n		else\n		{\n			$loop = FALSE;\n		}\n	}\n\n	if ( $n === 0 )\n	{\n		return \'Please include a sentence\';\n	}\n\n	return $sentence;\n}\n\n$text = \"Writing image code doesn\'t always mean better. should also pay attention to the smoothness and optimality of the helminth \";\n\necho uppercase( $text );</code></pre>\n\n<p>//Output</p>\n\n<p>Writing image code doesn&#39;t always mean better. Should also pay attention to the smoothness and optimality of the helminth</p>', '<pre>\n<code class=\"language-php\">&lt;?php\n/**\n * Verilmiş textdəki cümlələrin ilk hərfini böyüklə yazan proqram. Hazır funksiyalardan ( explode ) istifadə etmək olmaz.\n *\n * $text = \' suretli kod yazmaq her zaman daha yaxshi demek deyil.          seliqeye ve hellin optimalligina da fikir vermelidir\';\n *\n */\n\nfunction uppercase ( $text = NULL )\n{\n	$loop      = TRUE;\n	$n         = 0;\n	$sentence  = \'\';\n	$uppercase = FALSE;//Bu bizə cümlənin əvvəlində və ya .(nöqtə) dən sonra  boşluqları nəzərə almaqçün\n	// lazımdır\n	while ( $loop === TRUE )\n	{\n		if ( isset( $text[ $n ] ) )\n		{\n			if ( $n === 0 )\n			{\n				$uppercase = TRUE;\n			}\n			else\n			{\n				if ( $text[ $n - 1 ] == \'.\' )\n				{\n					$uppercase = TRUE;\n\n				}\n			}\n\n			if ( $uppercase === TRUE &amp;&amp; $text[ $n ] != \' \' )\n			{\n				$sentence  .= strtoupper( $text[ $n ] );\n				$uppercase = FALSE;\n			}\n			else\n			{\n				$sentence .= $text[ $n ];\n			}\n\n			$n++;\n		}\n		else\n		{\n			$loop = FALSE;\n		}\n	}\n\n	if ( $n === 0 )\n	{\n		return \'Please include a sentence\';\n	}\n\n	return $sentence;\n}\n\n$text = \' suretli kod yazmaq her zaman daha yaxshi demek deyil.          seliqeye ve hellin optimalligina da fikir vermelidir\';\n\necho uppercase( $text );</code></pre>\n\n<p>//Output</p>\n\n<p>Suretli kod yazmaq her zaman daha yaxshi demek deyil. Seliqeye ve hellin optimalligina da fikir vermelidir</p>', 8, 0, '2021-03-02 02:16:29', '2021-03-02 03:40:51'),
(3, 'A program that cuts the letter Y from the X character of the text. Ready functions (substr, strlen) cannot be used', 'Textin X-ci simvolundan başlayaraq Y qədər hərfi kəsib göstərən proqram. Hazır funksiyalardan ( substr, strlen ) istifadə etmək olmaz', 'a-program-that-cuts-the-letter-y-from-the-x-character-of-the-text-ready-functions-substr-strlen-cannot-be-used', 'textin-x-ci-simvolundan-baslayaraq-y-qeder-herfi-kesib-gosteren-proqram-hazir-funksiyalardan-substr-strlen-istifade-etmek-olmaz', '<pre>\n<code class=\"language-php\">&lt;?php\n/**\n * 3) A program that cuts the letter Y from the X character of the text. Ready functions (substr, strlen) cannot be used .\n */\n\nfunction mySubStr ( $text = NULL, $start = 0, $length = NULL )\n{\n	$output = \'\';\n\n	// Here if it was taken because you said that the 1st letter starts with 1, not 0 \n	if ( $start &lt; 0 )\n	{\n		if ( isset( $text[ $start ] ) )\n		{\n			for ( $i = 0; $i &lt; $length; $i++ )\n			{\n				if ( isset( $text[ $start + $i ] ) )\n				{\n					$output .= $text[ $start + $i ];\n				}\n				else\n				{\n					break;\n				}\n			}\n		}\n	}\n	else\n	{\n		if ( isset( $text[ $start - 1 ] ) )\n		{\n			for ( $i = 0; $i &lt; $length; $i++ )\n			{\n				if ( isset( $text[ $start + $i - 1 ] ) )\n				{\n					$output .= $text[ $start + $i - 1 ];\n				}\n				else\n				{\n					break;\n				}\n			}\n		}\n	}\n\n	return $output;\n}\n\n$x    = -4;\n$y    = 6;\n$text = \'This is the last assignment of the day. \';\n\necho mySubStr( $text, $x, $y );</code></pre>\n\n<p>//Output</p>\n\n<p>ay. Th</p>', '<pre>\n<code class=\"language-php\">&lt;?php\n/**\n * 3) Textin X-ci simvolundan başlayaraq Y qədər hərfi kəsib göstərən proqram. Hazır funksiyalardan ( substr, strlen ) istifadə etmək olmaz.\n */\n\nfunction mySubStr ( $text = NULL, $start = 0, $length = NULL )\n{\n	$output = \'\';\n\n	// Burada if Sizin 1 - ci hərfi 0 deyil 1 dən başlamasını dediyiniz üçün alındı\n	if ( $start &lt; 0 )\n	{\n		if ( isset( $text[ $start ] ) )\n		{\n			for ( $i = 0; $i &lt; $length; $i++ )\n			{\n				if ( isset( $text[ $start + $i ] ) )\n				{\n					$output .= $text[ $start + $i ];\n				}\n				else\n				{\n					break;\n				}\n			}\n		}\n	}\n	else\n	{\n		if ( isset( $text[ $start - 1 ] ) )\n		{\n			for ( $i = 0; $i &lt; $length; $i++ )\n			{\n				if ( isset( $text[ $start + $i - 1 ] ) )\n				{\n					$output .= $text[ $start + $i - 1 ];\n				}\n				else\n				{\n					break;\n				}\n			}\n		}\n	}\n\n	return $output;\n}\n\n$x    = -4;\n$y    = 6;\n$text = \'Bu gunluk son tapsiriq.\';\n\necho mySubStr( $text, $x, $y );</code></pre>\n\n<p>//Output</p>\n\n<p>riq.Bu</p>', 8, 0, '2021-03-02 02:25:46', '2021-03-02 03:41:58'),
(5, 'How to create a symbolic link for laravel website in cPanel', 'CPanel-də laravel veb səhifəsi üçün simvolik bir qısayol necə yaradılır', 'how-to-create-a-symbolic-link-for-laravel-website-in-cpanel', 'cpanel-de-laravel-veb-sehifesi-ucun-simvolik-bir-qisayol-nece-yaradilir', '<p><img alt=\"\" src=\"https://rahimsuleymanov.com/images/blogs/symlink_1614642696.PNG\" style=\"float:left\" /></p>\n\n<p>Creating symbolic links</p>\n\n<ol>\n	<li>delete the public / storage folder</li>\n	<li>Create a storage folder in the public_html folder</li>\n	<li>ln -s&nbsp; / home / u163060000 / domains / example.com / Projects / Project 1 / storage / app / public /* /home / u163060000 / domains / example.com / public_html / storage</li>\n</ol>', '<p><img alt=\"\" src=\"https://rahimsuleymanov.com/images/blogs/symlink_1614642994.PNG\" style=\"float:left\" /></p>\n\n<p>Simvolik ke&ccedil;idlər yaradılması</p>\n\n<ol>\n	<li>public/storage qovluğunu sil</li>\n	<li>public_html qovluğunda storage qovluğu yarat</li>\n	<li>ln -s /home / u163060000 / domains / example.com / Projects / Project 1/ storage / app / public/* /home / u163060000 / domains / example.com / public_html / storage</li>\n</ol>', 9, 0, '2021-03-02 04:06:12', '2021-07-13 18:02:09'),
(6, 'A program that prints letters in a given text from top to bottom according to the number of processing.', 'Verilmiş textdəki hərfləri işlənmə sayına görə yuxarıdan aşağı doğru çap edən proqram.', 'a-program-that-prints-letters-in-a-given-text-from-top-to-bottom-according-to-the-number-of-processing', 'verilmis-textdeki-herfleri-islenme-sayina-gore-yuxaridan-asagi-dogru-cap-eden-proqram', '<pre>\n<code class=\"language-php\">&lt;?php\n/**\n * 1) A program that prints letters in a given text from top to bottom according to the number of processing. You can use array and for, vvhile, foreach. array_ *, substr, strlen cannot be used. \n */\n\nfunction myRsort ( $text = NULL )\n{\n	$loop        = TRUE;\n	$diffLetters = [];\n	$n           = 0;\n	$myIn_array  = FALSE;\n	while ( $loop === TRUE )\n	{\n		if ( isset( $text[ $n ] ) )\n		{\n			// different letter\n			if ( ! empty( $diffLetters ) )\n			{\n				foreach ( $diffLetters as $diffLetter =&gt; $value )\n				{\n					if ( $diffLetter == $text[ $n ] )\n					{\n						$myIn_array                 = TRUE;\n						$diffLetters[ $text[ $n ] ] = $value + 1;\n					}\n				}\n			}\n\n			if ( $myIn_array !== TRUE )\n			{\n				$diffLetters[ $text[ $n ] ] = 1;\n			}\n			$myIn_array = FALSE;\n			$n++;\n		}\n		else\n		{\n			$loop = FALSE;\n		}\n	}\n\n	//    echo \'&lt;pre&gt;\';\n	//    return $diffLetters;\n\n	//I indexed the elements \n	$output      = [];\n	$bridgeArray = [];\n	foreach ( $diffLetters as $diffLetter =&gt; $value )\n	{\n		$bridgeArray[ $diffLetter ] = $value;\n		$output[]                   = $bridgeArray;\n		$bridgeArray                = [];\n	}\n\n	//Massivde herflerin sayina gore tersine duzdum\n	for ( $i = 0; $i &lt; count( $output ); $i++ )\n	{\n		foreach ( $output[ $i ] as $letter1 =&gt; $value1 )\n		{\n			for ( $j = 0; $j &lt; count( $output ); $j++ )\n			{\n				foreach ( $output[ $j ] as $letter2 =&gt; $value2 )\n				{\n					if ( $value1 &gt; $value2 )\n					{\n						$tem          = $output[ $i ];\n						$output[ $i ] = $output[ $j ];\n						$output[ $j ] = $tem;\n					}\n				}\n			}\n		}\n	}\n\n	echo \'&lt;pre&gt;\';\n\n	return $output;\n}\n\n$text = \'Programming\';\nprint_r( myRsort( $text ) );</code></pre>\n\n<pre>\nArray\n(\n    [0] =&gt; Array\n        (\n            [r] =&gt; 2\n        )\n\n    [1] =&gt; Array\n        (\n            [g] =&gt; 2\n        )\n\n    [2] =&gt; Array\n        (\n            [m] =&gt; 2\n        )\n\n    [3] =&gt; Array\n        (\n            [n] =&gt; 1\n        )\n\n    [4] =&gt; Array\n        (\n            [i] =&gt; 1\n        )\n\n    [5] =&gt; Array\n        (\n            [a] =&gt; 1\n        )\n\n    [6] =&gt; Array\n        (\n            [P] =&gt; 1\n        )\n\n    [7] =&gt; Array\n        (\n            [o] =&gt; 1\n        )\n\n)</pre>', '<pre>\n<code class=\"language-php\">&lt;?php\n/**\n * 1) Verilmiş textdəki hərfləri işlənmə sayına görə yuxarıdan aşağı doğru çap edən proqram. Array və for, vvhile, foreach istifadə edə bilərsiz. array_*, substr, strlen istifadə etmək olmaz.\n */\n\nfunction myRsort ( $text = NULL )\n{\n	$loop        = TRUE;\n	$diffLetters = [];\n	$n           = 0;\n	$myIn_array  = FALSE;\n	while ( $loop === TRUE )\n	{\n		if ( isset( $text[ $n ] ) )\n		{\n			// different letter\n			if ( ! empty( $diffLetters ) )\n			{\n				foreach ( $diffLetters as $diffLetter =&gt; $value )\n				{\n					if ( $diffLetter == $text[ $n ] )\n					{\n						$myIn_array                 = TRUE;\n						$diffLetters[ $text[ $n ] ] = $value + 1;\n					}\n				}\n			}\n\n			if ( $myIn_array !== TRUE )\n			{\n				$diffLetters[ $text[ $n ] ] = 1;\n			}\n			$myIn_array = FALSE;\n			$n++;\n		}\n		else\n		{\n			$loop = FALSE;\n		}\n	}\n\n	//    echo \'&lt;pre&gt;\';\n	//    return $diffLetters;\n\n	//elementleri indeksledim\n	$output      = [];\n	$bridgeArray = [];\n	foreach ( $diffLetters as $diffLetter =&gt; $value )\n	{\n		$bridgeArray[ $diffLetter ] = $value;\n		$output[]                   = $bridgeArray;\n		$bridgeArray                = [];\n	}\n\n	//Massivde herflerin sayina gore tersine duzdum\n	for ( $i = 0; $i &lt; count( $output ); $i++ )\n	{\n		foreach ( $output[ $i ] as $letter1 =&gt; $value1 )\n		{\n			for ( $j = 0; $j &lt; count( $output ); $j++ )\n			{\n				foreach ( $output[ $j ] as $letter2 =&gt; $value2 )\n				{\n					if ( $value1 &gt; $value2 )\n					{\n						$tem          = $output[ $i ];\n						$output[ $i ] = $output[ $j ];\n						$output[ $j ] = $tem;\n					}\n				}\n			}\n		}\n	}\n\n	echo \'&lt;pre&gt;\';\n\n	return $output;\n}\n\n$text = \'Proqramlasdirma\';\nprint_r( myRsort( $text ) );</code></pre>\n\n<p>//Output</p>\n\n<pre>\nArray\n(\n    [0] =&gt; Array\n        (\n            [r] =&gt; 3\n        )\n\n    [1] =&gt; Array\n        (\n            [a] =&gt; 3\n        )\n\n    [2] =&gt; Array\n        (\n            [m] =&gt; 2\n        )\n\n    [3] =&gt; Array\n        (\n            [i] =&gt; 1\n        )\n\n    [4] =&gt; Array\n        (\n            [P] =&gt; 1\n        )\n\n    [5] =&gt; Array\n        (\n            [d] =&gt; 1\n        )\n\n    [6] =&gt; Array\n        (\n            [o] =&gt; 1\n        )\n\n    [7] =&gt; Array\n        (\n            [s] =&gt; 1\n        )\n\n    [8] =&gt; Array\n        (\n            [q] =&gt; 1\n        )\n\n    [9] =&gt; Array\n        (\n            [l] =&gt; 1\n        )\n\n)</pre>', 8, 0, '2021-03-02 20:29:11', '2021-03-02 20:29:11'),
(7, 'A function that prints a given clock in a 24-hour format in a 12-hour format. This time you can use explode. However, date and similar features cannot be used.', '24 saatlıq formatında verilmiş saatı 12 saatlıq formatda çap edən funksiya. Bu dəfə explode istifadə edə bilərsiniz. Lakin, date və bənzəri funksiyalardan istifadə etmək olmaz.', 'a-function-that-prints-a-given-clock-in-a-24-hour-format-in-a-12-hour-format-this-time-you-can-use-explode-however-date-and-similar-features-cannot-be-used', '24-saatliq-formatinda-verilmis-saati-12-saatliq-formatda-cap-eden-funksiya-bu-defe-explode-istifade-ede-bilersiniz-lakin-date-ve-benzeri-funksiyalardan-istifade-etmek-olmaz', '<pre>\n<code class=\"language-php\">&lt;?php\n/**\n * 2) A function that prints a given clock in a 24-hour format in a 12-hour format. This time you can use explode. However, date and similar features cannot be used.\n */\n\nfunction talkTime ( $clock = NULL )\n{\n	$clock  = explode( \':\', $clock );\n	$medium = \'AM\';\n\n	$convert = FALSE;\n\n	if ( count( $clock ) === 2 )\n	{\n		if ( ctype_digit( $clock[ 0 ] ) &amp;&amp; ctype_digit( $clock[ 1 ] ) )\n		{\n			if ( $clock[ 0 ] &lt; 24 &amp;&amp; $clock[ 1 ] &lt; 60 )\n			{\n				if ( $clock[ 0 ] &gt; 12 )\n				{\n					$clock[ 0 ] = $clock[ 0 ] - 12;\n					$medium     = \'PM\';\n				}\n				$convert = TRUE;\n			}\n		}\n	}\n\n	if ( $convert === FALSE )\n	{\n		return \'Please, enter right date format!\';\n	}\n\n	return $clock[ 0 ] . \' : \' . $clock[ 1 ] . \' \' . $medium;\n}\n\n$saat1 = \'01:16\';\n$saat2 = \'03:30\';\n$saat3 = \'23:05\';\n\necho talkTime( $saat1 );</code></pre>\n\n<p>//Output</p>\n\n<p>01 : 16 AM</p>', '<pre>\n<code class=\"language-php\">&lt;?php\n/**\n * 2) 24 saatlıq formatında verilmiş saatı 12 saatlıq formatda çap edən funksiya. Bu dəfə explode istifadə edə bilərsiniz. Lakin, date və bənzəri funksiyalardan istifadə etmək olmaz.\n */\n\nfunction talkTime ( $clock = NULL )\n{\n	$clock  = explode( \':\', $clock );\n	$medium = \'AM\';\n\n	$convert = FALSE;\n\n	if ( count( $clock ) === 2 )\n	{\n		if ( ctype_digit( $clock[ 0 ] ) &amp;&amp; ctype_digit( $clock[ 1 ] ) )\n		{\n			if ( $clock[ 0 ] &lt; 24 &amp;&amp; $clock[ 1 ] &lt; 60 )\n			{\n				if ( $clock[ 0 ] &gt; 12 )\n				{\n					$clock[ 0 ] = $clock[ 0 ] - 12;\n					$medium     = \'PM\';\n				}\n				$convert = TRUE;\n			}\n		}\n	}\n\n	if ( $convert === FALSE )\n	{\n		return \'Please, enter right date format!\';\n	}\n\n	return $clock[ 0 ] . \' : \' . $clock[ 1 ] . \' \' . $medium;\n}\n\n$saat1 = \'01:16\';\n$saat2 = \'03:30\';\n$saat3 = \'23:05\';\n\necho talkTime( $saat1 );</code></pre>\n\n<p>//Output</p>\n\n<p>01 : 16 AM</p>', 8, 0, '2021-03-02 20:36:49', '2021-03-02 20:36:49'),
(8, 'Date given in the form of day-month-year, the program that prints in the format of month-year.', 'gün-ay-il formasında verilmiş tarixi gün, Ay il formatında çap edən proqram.', 'date-given-in-the-form-of-day-month-year-the-program-that-prints-in-the-format-of-month-year', 'gun-ay-il-formasinda-verilmis-tarixi-gun-ay-il-formatinda-cap-eden-proqram', '<pre>\n<code class=\"language-php\">&lt;?php\n/**\n * 3) Date given in the form of day-month-year, the program that prints in the format of month-year. You can use Explode. You can\'t use the array_ * functions, but you can use an array. date and similar ready-made features will not be available.\n */\n\nfunction myDate ( $date = NULL )\n{\n	$date    = explode( \'-\', $date );\n	$months  = [\n		\'January\',\n		\'February\',\n		\'March\',\n		\'April\',\n		\'May\',\n		\'June\',\n		\'July\',\n		\'August\',\n		\'September\',\n		\'October\',\n		\'November\',\n		\'December\',\n	];\n	$convert = FALSE;\n	if ( count( $date ) === 3 )\n	{\n		if ( ctype_digit( $date[ 0 ] ) &amp;&amp; ctype_digit( $date[ 1 ] ) )\n		{\n			if ( $date[ 0 ] &lt; 32 &amp;&amp; $date[ 1 ] &lt; 13 )\n			{\n				$date    = intval( $date[ 0 ] ) . \' \' . $months[ $date[ 1 ] - 1 ] . \', \' . $date[ 2 ];\n				$convert = TRUE;\n			}\n		}\n	}\n\n	if ( $convert === FALSE )\n	{\n		return \'Please, enter right date format!\';\n	}\n\n	return $date;\n}\n\n$tarix1 = \'07-04-2000\';\n$tarix2 = \'12-05-1977\';\necho myDate( $tarix1 );</code></pre>\n\n<p>//Output</p>\n\n<p>7 April, 2000</p>', '<pre>\n<code class=\"language-php\">&lt;?php\n/**\n * 3) gün-ay-il formasında verilmiş tarixi gün, Ay il formatında çap edən proqram. Explode istifadə edə bilərsiniz.  array_* funksiyalarından istifadə etmək olmaz, amma array istifadə edə bilərsiz. date və bənzəri hazır funksiyalar olmaz.\n */\n\nfunction myDate ( $date = NULL )\n{\n	$date    = explode( \'-\', $date );\n	$months  = [\n		\'January\',\n		\'February\',\n		\'March\',\n		\'April\',\n		\'May\',\n		\'June\',\n		\'July\',\n		\'August\',\n		\'September\',\n		\'October\',\n		\'November\',\n		\'December\',\n	];\n	$convert = FALSE;\n	if ( count( $date ) === 3 )\n	{\n		if ( ctype_digit( $date[ 0 ] ) &amp;&amp; ctype_digit( $date[ 1 ] ) )\n		{\n			if ( $date[ 0 ] &lt; 32 &amp;&amp; $date[ 1 ] &lt; 13 )\n			{\n				$date    = intval( $date[ 0 ] ) . \' \' . $months[ $date[ 1 ] - 1 ] . \', \' . $date[ 2 ];\n				$convert = TRUE;\n			}\n		}\n	}\n\n	if ( $convert === FALSE )\n	{\n		return \'Please, enter right date format!\';\n	}\n\n	return $date;\n}\n\n$tarix1 = \'07-04-2000\';\n$tarix2 = \'12-05-1977\';\necho myDate( $tarix1 );</code></pre>\n\n<p>//Output</p>\n\n<p>7 April, 2000</p>', 8, 0, '2021-03-02 20:39:08', '2021-03-02 20:39:08'),
(9, 'Laravel manual login function', 'Laravel manual  login funksiyası', 'laravel-manual-login-function', 'laravel-manual-login-funksiyasi', '<pre>\n<code class=\"language-php\">$user = User::where(\'email\',\'=\',$request-&gt;email)-&gt;first();\n\nif ($user !== null)\n{\n    if (password_verify($request-&gt;password,$user-&gt;password))\n    {\n        Auth::loginUsingId($user-&gt;id, TRUE);\n        return redirect()-&gt;route(\'one\');\n    }\n    else\n    {\n        return view(\'auth.login\')-&gt;with(\'error\',\'Password is incorrect\');\n    }\n}\nelse\n{\n    return view(\'auth.login\')-&gt;with(\'error\',\'Email or password is incorrect\');\n}</code></pre>\n\n<p>&nbsp;</p>', '<pre>\n<code class=\"language-php\">$user = User::where(\'email\',\'=\',$request-&gt;email)-&gt;first();\n\nif ($user !== null)\n{\n    if (password_verify($request-&gt;password,$user-&gt;password))\n    {\n        Auth::loginUsingId($user-&gt;id, TRUE);\n        return redirect()-&gt;route(\'one\');\n    }\n    else\n    {\n        return view(\'auth.login\')-&gt;with(\'error\',\'Password is incorrect\');\n    }\n}\nelse\n{\n    return view(\'auth.login\')-&gt;with(\'error\',\'Email or password is incorrect\');\n}</code></pre>\n\n<p>&nbsp;</p>', 5, 0, '2021-03-03 15:17:36', '2021-03-03 15:18:20'),
(10, 'Validation Localization', 'Doğrulama Lokallaşdırma', 'validation-localization', 'dogrulama-lokallasdirma', '<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Http\\Requests;\n\nuse Illuminate\\Foundation\\Http\\FormRequest;\n\nclass signInUpRequest extends FormRequest\n{\n    /**\n     * Determine if the user is authorized to make this request.\n     *\n     * @return bool\n     */\n    public function authorize()\n    {\n        return true;\n    }\n\n    /**\n     * Get the validation rules that apply to the request.\n     *\n     * @return array\n     */\n    public function rules()\n    {\n        return [\n            \'fullName\'=&gt;\'required|min:3|max:50\',\n            \'email\'=&gt;\'required|email|max:255|unique:users,email\',\n            \'password\' =&gt; \'min:8|required_with:password_confirmation|same:password_confirmation\',\n            \'password_confirmation\' =&gt; \'min:8\'\n        ];\n    }\n\n    public function attributes()\n    {\n        return [\n            \'fullName\' =&gt; __(\'home.full_name\'),\n            \'email\' =&gt; __(\'home.email_address\'),\n            \'password\' =&gt; __(\'home.password\'),\n            \'password_confirmation\' =&gt; __(\'home.confirm_password\'),\n        ];\n    }\n}\n</code></pre>\n\n<p>&nbsp;</p>', '<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Http\\Requests;\n\nuse Illuminate\\Foundation\\Http\\FormRequest;\n\nclass signInUpRequest extends FormRequest\n{\n    /**\n     * Determine if the user is authorized to make this request.\n     *\n     * @return bool\n     */\n    public function authorize()\n    {\n        return true;\n    }\n\n    /**\n     * Get the validation rules that apply to the request.\n     *\n     * @return array\n     */\n    public function rules()\n    {\n        return [\n            \'fullName\'=&gt;\'required|min:3|max:50\',\n            \'email\'=&gt;\'required|email|max:255|unique:users,email\',\n            \'password\' =&gt; \'min:8|required_with:password_confirmation|same:password_confirmation\',\n            \'password_confirmation\' =&gt; \'min:8\'\n        ];\n    }\n\n    public function attributes()\n    {\n        return [\n            \'fullName\' =&gt; __(\'home.full_name\'),\n            \'email\' =&gt; __(\'home.email_address\'),\n            \'password\' =&gt; __(\'home.password\'),\n            \'password_confirmation\' =&gt; __(\'home.confirm_password\'),\n        ];\n    }\n}\n</code></pre>\n\n<p>&nbsp;</p>', 5, 0, '2021-03-04 12:28:49', '2021-03-04 12:28:49'),
(12, 'Send an email in Laravel', 'Laraveldə email göndərmək', 'send-an-email-in-laravel', 'laravelde-email-gondermek', '<p>&nbsp;1. Make the following changes to the .env file</p>\n\n<pre>\n<code class=\"language-php\">MAIL_MAILER=smtp\nMAIL_HOST=smtp.googlemail.com\nMAIL_PORT=465\nMAIL_USERNAME=youremail@gmail.com\nMAIL_PASSWORD=Your Password\nMAIL_ENCRYPTION=ssl\nMAIL_FROM_ADDRESS=youremail@gmail.com\nMAIL_FROM_NAME=\"${APP_NAME}\"</code></pre>\n\n<p>2. php artisan make:mail SignUp --markdown = emails.signInUp.signUp run the command</p>\n\n<p>3. Make the following changes to the In the controller which we will use ... \\ app \\ Mail \\ signInUp.php</p>\n\n<pre>\n<code class=\"language-php\">$title                  = __(\'home.confirmationTitle\');\n$link                   = url(\'/confirmationUsers/\'.$user-&gt;id.\'/\'.$user-&gt;email);\n$text                   = __(\'home.confirmationMail\');\n\n$details = [\n    \'title\' =&gt; $title,\n    \'link\'  =&gt; $link,\n    \'body\'  =&gt; $text\n];\nMail::to($request-&gt;email)-&gt;send(new SignUp($details));</code></pre>\n\n<p>4. Change ... \\ app \\ Mail \\ signInUp.php as follows</p>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Mail;\n\nuse Illuminate\\Bus\\Queueable;\nuse Illuminate\\Contracts\\Queue\\ShouldQueue;\nuse Illuminate\\Mail\\Mailable;\nuse Illuminate\\Queue\\SerializesModels;\n\nclass SignUp extends Mailable\n{\n    use Queueable, SerializesModels;\n    public $details;\n\n    /**\n     * Create a new message instance.\n     *\n     * @return void\n     */\n    public function __construct($details)\n    {\n        $this-&gt;details = $details;\n    }\n\n    /**\n     * Build the message.\n     *\n     * @return $this\n     */\n    public function build()\n    {\n        return $this-&gt;subject(__(\'home.confirmationSubject\'))\n            -&gt;markdown(\'emails.signInUp.signUp\');\n    }\n}\n</code></pre>\n\n<p>5. Change ... \\ resources \\ views \\ emails \\ signInUp \\ signUp.blade.php as follows.</p>\n\n<pre>\n<code class=\"language-php\">@component(\'mail::layout\')\n    {{-- Header --}}\n    @slot(\'header\')\n        @component(\'mail::header\', [\'url\' =&gt; config(\'app.url\')])\n        {{ config(\'app.name\') }}\n        @endcomponent\n    @endslot\n    {{-- Body --}}\n    {{$details[\'title\']}}\n\n    {{-- Subcopy --}}\n    @isset($details[\'body\'])\n        @slot(\'subcopy\')\n            @component(\'mail::subcopy\')\n                {{$details[\'body\']}}\n                &lt;div style=\"text-align: center\"&gt;\n                    &lt;a href=\"{{ $details[\'link\'] }}\" class=\"button button-green\"&gt;{{ __(\'home.confirm\') }}&lt;/a&gt;\n                &lt;/div&gt;\n            @endcomponent\n        @endslot\n    @endisset\n\n    {{-- Footer --}}\n    @slot(\'footer\')\n        @component(\'mail::footer\')\n            © {{ date(\'Y\') }} {{ config(\'app.name\') }}. Group\n        @endcomponent\n    @endslot\n@endcomponent\n</code></pre>\n\n<p>The resulting email will be mailed as follows.</p>\n\n<p><img alt=\"\" src=\"https://rahimsuleymanov.com/images/blogs/mailEn_1614870128.PNG\" style=\"float:left\" /></p>', '<p>&nbsp;1. .env faylında aşağıdakı dəyişiklikləri etmək&nbsp;</p>\n\n<pre>\n<code class=\"language-php\">MAIL_MAILER=smtp\nMAIL_HOST=smtp.googlemail.com\nMAIL_PORT=465\nMAIL_USERNAME=youremail@gmail.com\nMAIL_PASSWORD=Your Password\nMAIL_ENCRYPTION=ssl\nMAIL_FROM_ADDRESS=youremail@gmail.com\nMAIL_FROM_NAME=\"${APP_NAME}\"</code></pre>\n\n<p>2. php artisan make:mail SignUp --markdown=emails.signInUp.signUp əmrini &ccedil;alışdırmaq</p>\n\n<p>3. ...\\app\\Mail\\signInUp.php -i istifadə edəcəyimiz controllerdə aşağıdakıları daxil etmək.</p>\n\n<pre>\n<code class=\"language-php\">$title                  = __(\'home.confirmationTitle\');\n$link                   = url(\'/confirmationUsers/\'.$user-&gt;id.\'/\'.$user-&gt;email);\n$text                   = __(\'home.confirmationMail\');\n\n$details = [\n    \'title\' =&gt; $title,\n    \'link\'  =&gt; $link,\n    \'body\'  =&gt; $text\n];\nMail::to($request-&gt;email)-&gt;send(new SignUp($details));</code></pre>\n\n<p>4.&nbsp;...\\app\\Mail\\signInUp.php -i aşağıdakı kimi dəyişmək</p>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Mail;\n\nuse Illuminate\\Bus\\Queueable;\nuse Illuminate\\Contracts\\Queue\\ShouldQueue;\nuse Illuminate\\Mail\\Mailable;\nuse Illuminate\\Queue\\SerializesModels;\n\nclass SignUp extends Mailable\n{\n    use Queueable, SerializesModels;\n    public $details;\n\n    /**\n     * Create a new message instance.\n     *\n     * @return void\n     */\n    public function __construct($details)\n    {\n        $this-&gt;details = $details;\n    }\n\n    /**\n     * Build the message.\n     *\n     * @return $this\n     */\n    public function build()\n    {\n        return $this-&gt;subject(__(\'home.confirmationSubject\'))\n            -&gt;markdown(\'emails.signInUp.signUp\');\n    }\n}\n</code></pre>\n\n<p>5. ...\\ resources \\ views \\ emails \\ signInUp \\ signUp.blade.php -ni aşağıdakı kimi dəyişmək.</p>\n\n<pre>\n<code class=\"language-php\">@component(\'mail::layout\')\n    {{-- Header --}}\n    @slot(\'header\')\n        @component(\'mail::header\', [\'url\' =&gt; config(\'app.url\')])\n        {{ config(\'app.name\') }}\n        @endcomponent\n    @endslot\n    {{-- Body --}}\n    {{$details[\'title\']}}\n\n    {{-- Subcopy --}}\n    @isset($details[\'body\'])\n        @slot(\'subcopy\')\n            @component(\'mail::subcopy\')\n                {{$details[\'body\']}}\n                &lt;div style=\"text-align: center\"&gt;\n                    &lt;a href=\"{{ $details[\'link\'] }}\" class=\"button button-green\"&gt;{{ __(\'home.confirm\') }}&lt;/a&gt;\n                &lt;/div&gt;\n            @endcomponent\n        @endslot\n    @endisset\n\n    {{-- Footer --}}\n    @slot(\'footer\')\n        @component(\'mail::footer\')\n            © {{ date(\'Y\') }} {{ config(\'app.name\') }}. Group\n        @endcomponent\n    @endslot\n@endcomponent\n</code></pre>\n\n<p>Nəticədə daxil edilən emailə aşağıdakı kimi mail g&ouml;ndəriləcək.</p>\n\n<p><img alt=\"\" src=\"https://rahimsuleymanov.com/images/blogs/mail_1614869176.PNG\" /></p>', 5, 0, '2021-03-04 19:02:27', '2021-03-23 02:01:24'),
(13, 'How to validate Route Parameters in Laravel', 'Laravel-də route parametrlərini necə validate etmək olar', 'how-to-validate-route-parameters-in-laravel', 'laravel-de-route-parametrlerini-nece-validate-etmek-olar', '<pre>\n<code class=\"language-php\">public function confirmationUsers(Request $request,$id,$email)\n{\n    $request-&gt;merge([\'id\' =&gt; $id,\'email\'=&gt;$email]) ;\n\n    $validator = Validator::make($request-&gt;all(), [\n        \'id\'=&gt;\'integer\'\n    ]);\n\n    if ($validator-&gt;fails())\n    {\n        //get errors\n        //$error_message  = $validator-&gt;messages();\n        return abort(404,__(\'error.not_found\'));\n    }\n    // your codes...\n}</code></pre>\n\n<p>&nbsp;</p>', '<pre>\n<code class=\"language-php\">public function confirmationUsers(Request $request,$id,$email)\n{\n    $request-&gt;merge([\'id\' =&gt; $id,\'email\'=&gt;$email]) ;\n\n    $validator = Validator::make($request-&gt;all(), [\n        \'id\'=&gt;\'integer\'\n    ]);\n\n    if ($validator-&gt;fails())\n    {\n        //get errors\n        //$error_message  = $validator-&gt;messages();\n        return abort(404,__(\'error.not_found\'));\n    }\n    // your codes...\n}</code></pre>\n\n<p>&nbsp;</p>', 5, 0, '2021-03-04 21:45:18', '2021-05-06 07:27:19'),
(14, 'How to validate input data using ajax in laravel', 'Laravel-də ajax istifadə edərək input məlumatlarını necə təsdiqləmək olar', 'how-to-validate-input-data-using-ajax-in-laravel', 'laravel-de-ajax-istifade-ederek-input-melumatlarini-nece-tesdiqlemek-olar', '<pre>\n<code class=\"language-php\">@extends(\'front.layout.master\')\n\n@section(\'title\')\n    {{ __(\'home.password_recovery\') }}\n@endsection\n\n@section(\'css\')\n\n@endsection\n\n@section(\'content\')\n    &lt;div class=\"container py-4 py-lg-5 my-4\"&gt;\n        &lt;div class=\"row justify-content-center\"&gt;\n            &lt;div class=\"col-lg-8 col-md-10\"&gt;\n                &lt;h2 class=\"h3 mb-4 password-recovery-title\"&gt;{{ __(\'home.forgot_password?\') }}&lt;/h2&gt;\n                &lt;p class=\"font-size-md\"&gt;{{ __(\'home.change_your_password_in_three_easy_steps_this_helps_to_keep_your_new_password_secure\') }}.&lt;/p&gt;\n                &lt;ol class=\"list-unstyled font-size-md\"&gt;\n                    &lt;li&gt;&lt;span class=\"text-primary mr-2\"&gt;1.&lt;/span&gt;{{ __(\'home.fill_in_your_email_address_below\') }}.&lt;/li&gt;\n                    &lt;li&gt;&lt;span class=\"text-primary mr-2\"&gt;2.&lt;/span&gt;{{ __(\'home.we_ll_email_you_a_temporary_code\') }}.&lt;/li&gt;\n                    &lt;li&gt;&lt;span class=\"text-primary mr-2\"&gt;3.&lt;/span&gt;{{ __(\'home.use_the_code_to_change_your_password_on_our_secure_website\') }}.&lt;/li&gt;\n                &lt;/ol&gt;\n                &lt;div class=\"card py-2 mt-4\"&gt;\n                    &lt;form class=\"card-body needs-validation\" novalidate=\"\" onsubmit=\"return false\"&gt;\n                        &lt;div class=\"form-group\"&gt;\n                            &lt;label for=\"recover-email\"&gt;{{ __(\'home.enter_your_email_address\') }}&lt;/label&gt;\n                            &lt;input class=\"form-control\" type=\"email\" id=\"recover-email\"&gt;\n                            &lt;div class=\"feedback\" id=\"emailErrorRe\"&gt;&lt;/div&gt;\n                        &lt;/div&gt;\n\n                        &lt;div class=\"form-group\"&gt;\n                            &lt;label for=\"recover-email\"&gt;{{ __(\'home.code\') }}&lt;/label&gt;\n                            &lt;input class=\"form-control\" type=\"text\" id=\"recover-code\"&gt;\n                            &lt;div class=\"feedback\" id=\"codeErrorRe\"&gt;&lt;/div&gt;\n                        &lt;/div&gt;\n\n                        &lt;button class=\"btn btn-primary\" id=\"recoveryBtn\" type=\"button\"&gt;{{ __(\'home.get_new_password\') }}&lt;/button&gt;\n                    &lt;/form&gt;\n                &lt;/div&gt;\n            &lt;/div&gt;\n        &lt;/div&gt;\n    &lt;/div&gt;\n@endsection\n\n@section(\'js\')\n    &lt;script&gt;\n        $(document).ready(function () {\n            $(\'#recoveryBtn\').click(function () {\n                $(this).prop(\'disabled\',true);\n                $(\'.feedback\').html(\'\');\n                let email  = $(\'#recover-email\').val();\n                let code   = $(\'#recover-code\').val();\n                if (email === \'\' || code === \'\')\n                {\n                    toastr.error(\"{{ __(\'toastr.incorrect_email\') }}\", \"{{ __(\"toastr.attention\") }}\");\n                    $(\'#recoveryBtn\').prop(\'disabled\',false);\n                    return ;\n                }\n                $.ajax({\n                    type:\'POST\',\n                    data:{email:email,code:code},\n                    url:\"{!! route(\'password.recovery.code.post\') !!}\",\n                    success:function (response) {\n                        if (response === \'notFound\')\n                        {\n                            toastr.error(\"{{ __(\'toastr.incorrect_email\') }}\", \"{{ __(\"toastr.attention\") }}\");\n                        }\n                        else\n                        {\n                            alert(\'response\')\n                        }\n                        $(\'#recoveryBtn\').prop(\'disabled\',false);\n                    },\n                    error: function(myErrors)\n                    {\n                        $.each(myErrors.responseJSON.errors, function (key, item)\n                        {\n                            $(\'#\'+key+\'ErrorRe\').removeAttr(\'class\').attr(\'class\',\'feedback \' +\n                                \'recoveryErrors\').html(\'\').html(item);\n                        });\n                        $(\'#recoveryBtn\').prop(\'disabled\',false);\n                    }\n                })\n            })\n        });\n    &lt;/script&gt;\n@endsection\n</code></pre>\n\n<p>&nbsp;</p>', '<pre>\n<code class=\"language-php\">@extends(\'front.layout.master\')\n\n@section(\'title\')\n    {{ __(\'home.password_recovery\') }}\n@endsection\n\n@section(\'css\')\n\n@endsection\n\n@section(\'content\')\n    &lt;div class=\"container py-4 py-lg-5 my-4\"&gt;\n        &lt;div class=\"row justify-content-center\"&gt;\n            &lt;div class=\"col-lg-8 col-md-10\"&gt;\n                &lt;h2 class=\"h3 mb-4 password-recovery-title\"&gt;{{ __(\'home.forgot_password?\') }}&lt;/h2&gt;\n                &lt;p class=\"font-size-md\"&gt;{{ __(\'home.change_your_password_in_three_easy_steps_this_helps_to_keep_your_new_password_secure\') }}.&lt;/p&gt;\n                &lt;ol class=\"list-unstyled font-size-md\"&gt;\n                    &lt;li&gt;&lt;span class=\"text-primary mr-2\"&gt;1.&lt;/span&gt;{{ __(\'home.fill_in_your_email_address_below\') }}.&lt;/li&gt;\n                    &lt;li&gt;&lt;span class=\"text-primary mr-2\"&gt;2.&lt;/span&gt;{{ __(\'home.we_ll_email_you_a_temporary_code\') }}.&lt;/li&gt;\n                    &lt;li&gt;&lt;span class=\"text-primary mr-2\"&gt;3.&lt;/span&gt;{{ __(\'home.use_the_code_to_change_your_password_on_our_secure_website\') }}.&lt;/li&gt;\n                &lt;/ol&gt;\n                &lt;div class=\"card py-2 mt-4\"&gt;\n                    &lt;form class=\"card-body needs-validation\" novalidate=\"\" onsubmit=\"return false\"&gt;\n                        &lt;div class=\"form-group\"&gt;\n                            &lt;label for=\"recover-email\"&gt;{{ __(\'home.enter_your_email_address\') }}&lt;/label&gt;\n                            &lt;input class=\"form-control\" type=\"email\" id=\"recover-email\"&gt;\n                            &lt;div class=\"feedback\" id=\"emailErrorRe\"&gt;&lt;/div&gt;\n                        &lt;/div&gt;\n\n                        &lt;div class=\"form-group\"&gt;\n                            &lt;label for=\"recover-email\"&gt;{{ __(\'home.code\') }}&lt;/label&gt;\n                            &lt;input class=\"form-control\" type=\"text\" id=\"recover-code\"&gt;\n                            &lt;div class=\"feedback\" id=\"codeErrorRe\"&gt;&lt;/div&gt;\n                        &lt;/div&gt;\n\n                        &lt;button class=\"btn btn-primary\" id=\"recoveryBtn\" type=\"button\"&gt;{{ __(\'home.get_new_password\') }}&lt;/button&gt;\n                    &lt;/form&gt;\n                &lt;/div&gt;\n            &lt;/div&gt;\n        &lt;/div&gt;\n    &lt;/div&gt;\n@endsection\n\n@section(\'js\')\n    &lt;script&gt;\n        $(document).ready(function () {\n            $(\'#recoveryBtn\').click(function () {\n                $(this).prop(\'disabled\',true);\n                $(\'.feedback\').html(\'\');\n                let email  = $(\'#recover-email\').val();\n                let code   = $(\'#recover-code\').val();\n                if (email === \'\' || code === \'\')\n                {\n                    toastr.error(\"{{ __(\'toastr.incorrect_email\') }}\", \"{{ __(\"toastr.attention\") }}\");\n                    $(\'#recoveryBtn\').prop(\'disabled\',false);\n                    return ;\n                }\n                $.ajax({\n                    type:\'POST\',\n                    data:{email:email,code:code},\n                    url:\"{!! route(\'password.recovery.code.post\') !!}\",\n                    success:function (response) {\n                        if (response === \'notFound\')\n                        {\n                            toastr.error(\"{{ __(\'toastr.incorrect_email\') }}\", \"{{ __(\"toastr.attention\") }}\");\n                        }\n                        else\n                        {\n                            alert(\'response\')\n                        }\n                        $(\'#recoveryBtn\').prop(\'disabled\',false);\n                    },\n                    error: function(myErrors)\n                    {\n                        $.each(myErrors.responseJSON.errors, function (key, item)\n                        {\n                            $(\'#\'+key+\'ErrorRe\').removeAttr(\'class\').attr(\'class\',\'feedback \' +\n                                \'recoveryErrors\').html(\'\').html(item);\n                        });\n                        $(\'#recoveryBtn\').prop(\'disabled\',false);\n                    }\n                })\n            })\n        });\n    &lt;/script&gt;\n@endsection\n</code></pre>\n\n<p>&nbsp;</p>', 5, 0, '2021-03-06 10:46:19', '2021-03-06 10:46:19'),
(15, 'How to create and destroy cookie in Laravel', 'Laravel-də cookie necə yaradılır və yox edilir', 'how-to-create-and-destroy-cookie-in-laravel', 'laravel-de-cookie-nece-yaradilir-ve-yox-edilir', '<p>1.Create</p>\n\n<pre>\n<code class=\"language-php\">Cookie::queue(\n    Cookie::make(\'cookieName\', \'value\', \'minutes\')\n);</code></pre>\n\n<p>2.Get value</p>\n\n<pre>\n<code class=\"language-php\">Cookie::get(\'cookieName\');</code></pre>\n\n<p>3.Destroy cookie</p>\n\n<pre>\n<code class=\"language-php\">Cookie::queue(\n    Cookie::forget(\'cookieName\')\n);</code></pre>\n\n<p>&nbsp;</p>', '<p>&nbsp;1.Cookie yarat</p>\n\n<pre>\n<code class=\"language-php\">Cookie::queue(\n    Cookie::make(\'cookieAdi\', \'deyeri\', \'deqiqeler\')\n);</code></pre>\n\n<p>2.Cookie - nin dəyərin al</p>\n\n<pre>\n<code class=\"language-php\">Cookie::get(\'cookieAdi\');</code></pre>\n\n<p>3.Cookie - ni yox et</p>\n\n<pre>\n<code class=\"language-php\">Cookie::queue(\n    Cookie::forget(\'cookieAdi\')\n);</code></pre>\n\n<p>&nbsp;</p>', 5, 0, '2021-03-06 23:55:50', '2021-03-10 16:08:48'),
(16, 'laravel clear database cache', 'laravel artisan clear cache', 'laravel-clear-database-cache', 'laravel-artisan-clear-cache', '<pre>\n<code class=\"language-php\">php artisan view:clear \nphp artisan cache:clear\nphp artisan route:clear\nphp artisan config:clear</code></pre>\n\n<p>&nbsp;</p>', '<pre>\n<code class=\"language-php\">php artisan view:clear \nphp artisan cache:clear\nphp artisan route:clear\nphp artisan config:clear</code></pre>\n\n<p>&nbsp;</p>', 5, 0, '2021-03-10 15:59:09', '2021-03-10 15:59:09'),
(17, 'How to start  Development Server in PHP?', 'PHP -də development server necə başladılır?', 'how-to-start-development-server-in-php', 'php-de-development-server-nece-basladilir', '<pre>\n<code class=\"language-php\">php -S localhost:8000</code></pre>\n\n<p>&nbsp;</p>', '<pre>\n<code class=\"language-php\">php -S localhost:8000</code></pre>\n\n<p>&nbsp;</p>', 4, 0, '2021-03-13 23:48:09', '2021-03-13 23:48:09');
INSERT INTO `blogs` (`id`, `titleEn`, `titleAz`, `slugEn`, `slugAz`, `blogEn`, `blogAz`, `category_id`, `view`, `created_at`, `updated_at`) VALUES
(18, 'Sorting Table Row using Jquery Drag Drop with Ajax PHP', 'Ajax PHP ilə Jquery Drag Drop istifadə edərək Cədvəl Sırasını çeşidləmək', 'sorting-table-row-using-jquery-drag-drop-with-ajax-php', 'ajax-php-ile-jquery-drag-drop-istifade-ederek-cedvel-sirasini-cesidlemek', '<p><img alt=\"\" src=\"https://rahimsuleymanov.com/images/blogs/sorting-table-row-using-jquery-drag-drop-with-ajax-php-small_1616450130.jpg\" style=\"float:left; width:100%\" /></p>\n\n<p>Source Code</p>\n\n<p><span style=\"background-color:#f1c40f\">index.php</span>&nbsp;</p>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n$connect = mysqli_connect(\"localhost\", \"root\", \"\", \"testing\");\n$query = \"SELECT * FROM page ORDER BY page_order ASC\";\n$result = mysqli_query($connect, $query);\n?&gt;\n&lt;html&gt;\n &lt;head&gt;\n  &lt;title&gt;Sorting Table Row using JQuery Drag Drop with Ajax PHP&lt;/title&gt;\n  &lt;script src=\"http://code.jquery.com/jquery-1.10.2.js\"&gt;&lt;/script&gt;\n  &lt;script src=\"http://code.jquery.com/ui/1.11.2/jquery-ui.js\"&gt;&lt;/script&gt;\n  &lt;link rel=\"stylesheet\" href=\"https://maxcdn.bootstrapcdn.com/bootstrap/3.3.7/css/bootstrap.min.css\" &gt;\n  &lt;script src=\"https://maxcdn.bootstrapcdn.com/bootstrap/3.3.7/js/bootstrap.min.js\"&gt;&lt;/script&gt;\n  &lt;style&gt;\n   body\n   {\n    margin:0;\n    padding:0;\n    background-color:#f1f1f1;\n   }\n   .box\n   {\n    width:1270px;\n    padding:20px;\n    background-color:#fff;\n    border:1px solid #ccc;\n    border-radius:5px;\n    margin-top:25px;\n   }\n   #page_list li\n   {\n    padding:16px;\n    background-color:#f9f9f9;\n    border:1px dotted #ccc;\n    cursor:move;\n    margin-top:12px;\n   }\n   #page_list li.ui-state-highlight\n   {\n    padding:24px;\n    background-color:#ffffcc;\n    border:1px dotted #ccc;\n    cursor:move;\n    margin-top:12px;\n   }\n  &lt;/style&gt;\n &lt;/head&gt;\n &lt;body&gt;\n  &lt;div class=\"container box\"&gt;\n   &lt;h1 align=\"center\"&gt;Sorting Table Row using JQuery Drag Drop with Ajax PHP&lt;/h1&gt;\n   &lt;br /&gt;\n   &lt;ul class=\"list-unstyled\" id=\"page_list\"&gt;\n   &lt;?php \n   while($row = mysqli_fetch_array($result))\n   {\n    echo \'&lt;li id=\"\'.$row[\"page_id\"].\'\"&gt;\'.$row[\"page_title\"].\'&lt;/li&gt;\';\n   }\n   ?&gt;\n   &lt;/ul&gt;\n   &lt;input type=\"hidden\" name=\"page_order_list\" id=\"page_order_list\" /&gt;\n  &lt;/div&gt;\n &lt;/body&gt;\n&lt;/html&gt;\n\n&lt;script&gt;\n$(document).ready(function(){\n $( \"#page_list\" ).sortable({\n  placeholder : \"ui-state-highlight\",\n  update  : function(event, ui)\n  {\n   var page_id_array = new Array();\n   $(\'#page_list li\').each(function(){\n    page_id_array.push($(this).attr(\"id\"));\n   });\n   $.ajax({\n    url:\"update.php\",\n    method:\"POST\",\n    data:{page_id_array:page_id_array},\n    success:function(data)\n    {\n     alert(data);\n    }\n   });\n  }\n });\n\n});\n&lt;/script&gt;</code></pre>\n\n<p><span style=\"background-color:#f1c40f\">update.php</span>&nbsp;</p>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n//update.php\n$connect = mysqli_connect(\"localhost\", \"root\", \"\", \"testing\");\n//$page_id = $_POST[\"page_id_array\"];\nfor($i=0; $i&lt;count($_POST[\"page_id_array\"]); $i++)\n{\n $query = \"\n UPDATE page \n SET page_order = \'\".$i.\"\' \n WHERE page_id = \'\".$_POST[\"page_id_array\"][$i].\"\'\";\n mysqli_query($connect, $query);\n}\necho \'Page Order has been updated\'; \n\n?&gt;</code></pre>\n\n<p><span style=\"background-color:#f1c40f\">Database</span></p>\n\n<pre>\n<code class=\"language-sql\">--\n-- Database: `testing`\n--\n\n-- --------------------------------------------------------\n\n--\n-- Table structure for table `page`\n--\n\nCREATE TABLE IF NOT EXISTS `page` (\n  `page_id` int(11) NOT NULL,\n  `page_title` text NOT NULL,\n  `page_url` text NOT NULL,\n  `page_order` int(11) NOT NULL\n) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=latin1;\n\n--\n-- Dumping data for table `page`\n--\n\nINSERT INTO `page` (`page_id`, `page_title`, `page_url`, `page_order`) VALUES\n(1, \'JSON - Dynamic Dependent Dropdown List using Jquery and Ajax\', \'json-dynamic-dependent-dropdown-list-using-jquery-and-ajax\', 3),\n(2, \'Live Table Data Edit Delete using Tabledit Plugin in PHP\', \'live-table-data-edit-delete-using-tabledit-plugin-in-php\', 5),\n(3, \'Create Treeview with Bootstrap Treeview Ajax JQuery in PHP\\r\\n\', \'create-treeview-with-bootstrap-treeview-ajax-jquery-in-php\', 9),\n(4, \'Bootstrap Multiselect Dropdown with Checkboxes using Jquery in PHP\\r\\n\', \'bootstrap-multiselect-dropdown-with-checkboxes-using-jquery-in-php\', 0),\n(5, \'Facebook Style Popup Notification using PHP Ajax Bootstrap\\r\\n\', \'facebook-style-popup-notification-using-php-ajax-bootstrap\', 1),\n(6, \'Modal with Dynamic Previous &amp; Next Data Button by Ajax PHP\\r\\n\', \'modal-with-dynamic-previous-next-data-button-by-ajax-php\', 6),\n(7, \'How to Use Bootstrap Select Plugin with Ajax Jquery PHP\\r\\n\', \'how-to-use-bootstrap-select-plugin-with-ajax-jquery-php\', 7),\n(8, \'How to Load CSV File data into HTML Table Using AJAX jQuery\\r\\n\', \'how-to-load-csv-file-data-into-html-table-using-ajax-jquery\', 8),\n(9, \'Autocomplete Textbox using Typeahead with Ajax PHP Bootstrap\\r\\n\', \'autocomplete-textbox-using-typeahead-with-ajax-php-bootstrap\', 4),\n(10, \'Export Data to Excel in Codeigniter using PHPExcel\\r\\n\', \'export-data-to-excel-in-codeigniter-using-phpexcel\', 2);\n\n--\n-- Indexes for dumped tables\n--\n\n--\n-- Indexes for table `page`\n--\nALTER TABLE `page`\n  ADD PRIMARY KEY (`page_id`);\n\n--\n-- AUTO_INCREMENT for dumped tables\n--\n\n--\n-- AUTO_INCREMENT for table `page`\n--\nALTER TABLE `page`\n  MODIFY `page_id` int(11) NOT NULL AUTO_INCREMENT,AUTO_INCREMENT=11;</code></pre>\n\n<p>&nbsp;</p>', '<p>&nbsp;<img alt=\"\" src=\"https://rahimsuleymanov.com/images/blogs/sorting-table-row-using-jquery-drag-drop-with-ajax-php-small_1616450130.jpg\" style=\"float:left; width:100%\" /></p>\n\n<p>Source Code</p>\n\n<p><span style=\"background-color:#f1c40f\">index.php</span>&nbsp;</p>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n$connect = mysqli_connect(\"localhost\", \"root\", \"\", \"testing\");\n$query = \"SELECT * FROM page ORDER BY page_order ASC\";\n$result = mysqli_query($connect, $query);\n?&gt;\n&lt;html&gt;\n &lt;head&gt;\n  &lt;title&gt;Sorting Table Row using JQuery Drag Drop with Ajax PHP&lt;/title&gt;\n  &lt;script src=\"http://code.jquery.com/jquery-1.10.2.js\"&gt;&lt;/script&gt;\n  &lt;script src=\"http://code.jquery.com/ui/1.11.2/jquery-ui.js\"&gt;&lt;/script&gt;\n  &lt;link rel=\"stylesheet\" href=\"https://maxcdn.bootstrapcdn.com/bootstrap/3.3.7/css/bootstrap.min.css\" &gt;\n  &lt;script src=\"https://maxcdn.bootstrapcdn.com/bootstrap/3.3.7/js/bootstrap.min.js\"&gt;&lt;/script&gt;\n  &lt;style&gt;\n   body\n   {\n    margin:0;\n    padding:0;\n    background-color:#f1f1f1;\n   }\n   .box\n   {\n    width:1270px;\n    padding:20px;\n    background-color:#fff;\n    border:1px solid #ccc;\n    border-radius:5px;\n    margin-top:25px;\n   }\n   #page_list li\n   {\n    padding:16px;\n    background-color:#f9f9f9;\n    border:1px dotted #ccc;\n    cursor:move;\n    margin-top:12px;\n   }\n   #page_list li.ui-state-highlight\n   {\n    padding:24px;\n    background-color:#ffffcc;\n    border:1px dotted #ccc;\n    cursor:move;\n    margin-top:12px;\n   }\n  &lt;/style&gt;\n &lt;/head&gt;\n &lt;body&gt;\n  &lt;div class=\"container box\"&gt;\n   &lt;h1 align=\"center\"&gt;Sorting Table Row using JQuery Drag Drop with Ajax PHP&lt;/h1&gt;\n   &lt;br /&gt;\n   &lt;ul class=\"list-unstyled\" id=\"page_list\"&gt;\n   &lt;?php \n   while($row = mysqli_fetch_array($result))\n   {\n    echo \'&lt;li id=\"\'.$row[\"page_id\"].\'\"&gt;\'.$row[\"page_title\"].\'&lt;/li&gt;\';\n   }\n   ?&gt;\n   &lt;/ul&gt;\n   &lt;input type=\"hidden\" name=\"page_order_list\" id=\"page_order_list\" /&gt;\n  &lt;/div&gt;\n &lt;/body&gt;\n&lt;/html&gt;\n\n&lt;script&gt;\n$(document).ready(function(){\n $( \"#page_list\" ).sortable({\n  placeholder : \"ui-state-highlight\",\n  update  : function(event, ui)\n  {\n   var page_id_array = new Array();\n   $(\'#page_list li\').each(function(){\n    page_id_array.push($(this).attr(\"id\"));\n   });\n   $.ajax({\n    url:\"update.php\",\n    method:\"POST\",\n    data:{page_id_array:page_id_array},\n    success:function(data)\n    {\n     alert(data);\n    }\n   });\n  }\n });\n\n});\n&lt;/script&gt;</code></pre>\n\n<p><span style=\"background-color:#f1c40f\">update.php</span>&nbsp;</p>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n//update.php\n$connect = mysqli_connect(\"localhost\", \"root\", \"\", \"testing\");\n//$page_id = $_POST[\"page_id_array\"];\nfor($i=0; $i&lt;count($_POST[\"page_id_array\"]); $i++)\n{\n $query = \"\n UPDATE page \n SET page_order = \'\".$i.\"\' \n WHERE page_id = \'\".$_POST[\"page_id_array\"][$i].\"\'\";\n mysqli_query($connect, $query);\n}\necho \'Page Order has been updated\'; \n\n?&gt;</code></pre>\n\n<p><span style=\"background-color:#f1c40f\">Database</span></p>\n\n<pre>\n<code class=\"language-sql\">--\n-- Database: `testing`\n--\n\n-- --------------------------------------------------------\n\n--\n-- Table structure for table `page`\n--\n\nCREATE TABLE IF NOT EXISTS `page` (\n  `page_id` int(11) NOT NULL,\n  `page_title` text NOT NULL,\n  `page_url` text NOT NULL,\n  `page_order` int(11) NOT NULL\n) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=latin1;\n\n--\n-- Dumping data for table `page`\n--\n\nINSERT INTO `page` (`page_id`, `page_title`, `page_url`, `page_order`) VALUES\n(1, \'JSON - Dynamic Dependent Dropdown List using Jquery and Ajax\', \'json-dynamic-dependent-dropdown-list-using-jquery-and-ajax\', 3),\n(2, \'Live Table Data Edit Delete using Tabledit Plugin in PHP\', \'live-table-data-edit-delete-using-tabledit-plugin-in-php\', 5),\n(3, \'Create Treeview with Bootstrap Treeview Ajax JQuery in PHP\\r\\n\', \'create-treeview-with-bootstrap-treeview-ajax-jquery-in-php\', 9),\n(4, \'Bootstrap Multiselect Dropdown with Checkboxes using Jquery in PHP\\r\\n\', \'bootstrap-multiselect-dropdown-with-checkboxes-using-jquery-in-php\', 0),\n(5, \'Facebook Style Popup Notification using PHP Ajax Bootstrap\\r\\n\', \'facebook-style-popup-notification-using-php-ajax-bootstrap\', 1),\n(6, \'Modal with Dynamic Previous &amp; Next Data Button by Ajax PHP\\r\\n\', \'modal-with-dynamic-previous-next-data-button-by-ajax-php\', 6),\n(7, \'How to Use Bootstrap Select Plugin with Ajax Jquery PHP\\r\\n\', \'how-to-use-bootstrap-select-plugin-with-ajax-jquery-php\', 7),\n(8, \'How to Load CSV File data into HTML Table Using AJAX jQuery\\r\\n\', \'how-to-load-csv-file-data-into-html-table-using-ajax-jquery\', 8),\n(9, \'Autocomplete Textbox using Typeahead with Ajax PHP Bootstrap\\r\\n\', \'autocomplete-textbox-using-typeahead-with-ajax-php-bootstrap\', 4),\n(10, \'Export Data to Excel in Codeigniter using PHPExcel\\r\\n\', \'export-data-to-excel-in-codeigniter-using-phpexcel\', 2);\n\n--\n-- Indexes for dumped tables\n--\n\n--\n-- Indexes for table `page`\n--\nALTER TABLE `page`\n  ADD PRIMARY KEY (`page_id`);\n\n--\n-- AUTO_INCREMENT for dumped tables\n--\n\n--\n-- AUTO_INCREMENT for table `page`\n--\nALTER TABLE `page`\n  MODIFY `page_id` int(11) NOT NULL AUTO_INCREMENT,AUTO_INCREMENT=11;</code></pre>\n\n<p>&nbsp;</p>', 4, 0, '2021-03-23 02:00:13', '2021-03-23 02:11:23'),
(19, 'Password Validation', 'Parolun təsdiqlənməsi', 'password-validation', 'parolun-tesdiqlenmesi', '<p>php artisan make:rule IsValidPassword</p>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Rules;\n\nuse Illuminate\\Contracts\\Validation\\Rule;\nuse Illuminate\\Support\\Str;\n\nclass IsValidPassword implements Rule\n{\n    /**\n     * Determine if the Length Validation Rule passes.\n     *\n     * @var boolean\n     */\n    public bool $lengthPasses = true;\n\n    /**\n     * Determine if the Uppercase Validation Rule passes.\n     *\n     * @var boolean\n     */\n    public bool $uppercasePasses = true;\n\n    /**\n     * Determine if the Numeric Validation Rule passes.\n     *\n     * @var boolean\n     */\n    public bool $numericPasses = true;\n\n    /**\n     * Determine if the Special Character Validation Rule passes.\n     *\n     * @var boolean\n     */\n    public bool $specialCharacterPasses = true;\n\n    /**\n     * Determine if the validation rule passes.\n     *\n     * @param  string  $attribute\n     * @param  mixed  $value\n     * @return bool\n     */\n    public function passes($attribute, $value)\n    {\n        $this-&gt;lengthPasses = (Str::length($value) &gt;= 8);\n        $this-&gt;uppercasePasses = (Str::lower($value) !== $value);\n        $this-&gt;numericPasses = ((bool) preg_match(\'/[0-9]/\', $value));\n        $this-&gt;specialCharacterPasses = ((bool) preg_match(\'/[^A-Za-z0-9]/\', $value));\n\n        return ($this-&gt;lengthPasses &amp;&amp; $this-&gt;uppercasePasses &amp;&amp; $this-&gt;numericPasses &amp;&amp; $this-&gt;specialCharacterPasses);\n    }\n\n    /**\n     * Get the validation error message.\n     *\n     * @return string\n     */\n    public function message()\n    {\n        if (!$this-&gt;lengthPasses)\n        {\n            return \'The :attribute must be at least 8 characters.\';\n        }\n        elseif (!$this-&gt;uppercasePasses)\n        {\n            return \'The :attribute must contain at least one uppercase character.\';\n        }\n        elseif (!$this-&gt;numericPasses)\n        {\n            return \'The :attribute must contain at least one number.\';\n        }\n        else\n        {\n            return \'The :attribute must contain one special character.\';\n        }\n    }\n}\n</code></pre>\n\n<pre>\n<code class=\"language-php\">$request-&gt;validate([\n    \'password\'              =&gt; [\'required\',\'max:255\',new isValidPassword(),\'required_with:password_confirmation\',\'same:password_confirmation\'],\n    \'password_confirmation\' =&gt; \'required|min:8\'\n]);</code></pre>', '<p>php artisan make:rule IsValidPassword</p>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Rules;\n\nuse Illuminate\\Contracts\\Validation\\Rule;\nuse Illuminate\\Support\\Str;\n\nclass IsValidPassword implements Rule\n{\n    /**\n     * Determine if the Length Validation Rule passes.\n     *\n     * @var boolean\n     */\n    public bool $lengthPasses = true;\n\n    /**\n     * Determine if the Uppercase Validation Rule passes.\n     *\n     * @var boolean\n     */\n    public bool $uppercasePasses = true;\n\n    /**\n     * Determine if the Numeric Validation Rule passes.\n     *\n     * @var boolean\n     */\n    public bool $numericPasses = true;\n\n    /**\n     * Determine if the Special Character Validation Rule passes.\n     *\n     * @var boolean\n     */\n    public bool $specialCharacterPasses = true;\n\n    /**\n     * Determine if the validation rule passes.\n     *\n     * @param  string  $attribute\n     * @param  mixed  $value\n     * @return bool\n     */\n    public function passes($attribute, $value)\n    {\n        $this-&gt;lengthPasses = (Str::length($value) &gt;= 8);\n        $this-&gt;uppercasePasses = (Str::lower($value) !== $value);\n        $this-&gt;numericPasses = ((bool) preg_match(\'/[0-9]/\', $value));\n        $this-&gt;specialCharacterPasses = ((bool) preg_match(\'/[^A-Za-z0-9]/\', $value));\n\n        return ($this-&gt;lengthPasses &amp;&amp; $this-&gt;uppercasePasses &amp;&amp; $this-&gt;numericPasses &amp;&amp; $this-&gt;specialCharacterPasses);\n    }\n\n    /**\n     * Get the validation error message.\n     *\n     * @return string\n     */\n    public function message()\n    {\n        if (!$this-&gt;lengthPasses)\n        {\n            return \'The :attribute must be at least 8 characters.\';\n        }\n        elseif (!$this-&gt;uppercasePasses)\n        {\n            return \'The :attribute must contain at least one uppercase character.\';\n        }\n        elseif (!$this-&gt;numericPasses)\n        {\n            return \'The :attribute must contain at least one number.\';\n        }\n        else\n        {\n            return \'The :attribute must contain one special character.\';\n        }\n    }\n}\n</code></pre>\n\n<pre>\n<code class=\"language-php\">$request-&gt;validate([\n    \'password\'              =&gt; [\'required\',\'max:255\',new isValidPassword(),\'required_with:password_confirmation\',\'same:password_confirmation\'],\n    \'password_confirmation\' =&gt; \'required|min:8\'\n]);</code></pre>\n\n<p>&nbsp;</p>', 5, 0, '2021-04-06 04:26:35', '2021-04-06 04:48:11'),
(20, 'Registration Validation with jQuery', 'jQuery ilə qeydiyyat doğrulaması', 'registration-validation-with-jquery', 'jquery-ile-qeydiyyat-dogrulamasi', '<pre>\n<code class=\"language-html\">&lt;form action=\"\" id=\"application-form\" method=\"post\" autocomplete=\"off\" enctype=\"multipart/form-data\"&gt;\n        @csrf\n        &lt;div class=\"form-group mb-3\"&gt;\n            &lt;label for=\"name\" class=\"form-label\"&gt;Name&lt;/label&gt;\n            &lt;input type=\"text\" class=\"form-control\" id=\"name\" name=\"name\" aria-describedby=\"nameHelp\" placeholder=\"Enter name\" wire:model.defer=\"name\"&gt;\n            @error(\'name\')&lt;small id=\"nameHelp-php\" class=\"form-text text-danger\"&gt;{{ $message }}&lt;/small&gt;@enderror\n            &lt;small id=\"nameHelp-js\" class=\"form-text text-danger\"&gt;&lt;/small&gt;\n        &lt;/div&gt;\n\n        &lt;div class=\"form-group mb-3\"&gt;\n            &lt;label for=\"email\" class=\"form-label\"&gt;Email&lt;/label&gt;\n            &lt;input type=\"text\" class=\"form-control\" id=\"email\" name=\"email\" aria-describedby=\"emailHelp\" placeholder=\"Enter email\" wire:model.defer=\"email\"&gt;\n            @error(\'email\')&lt;small id=\"emailHelp-php\" class=\"form-text text-danger\"&gt;{{ $message }}&lt;/small&gt;@enderror\n            &lt;small id=\"emailHelp-js\" class=\"form-text text-danger\"&gt;&lt;/small&gt;\n        &lt;/div&gt;\n\n        &lt;div class=\"form-group mb-3\"&gt;\n            &lt;label for=\"password\" class=\"form-label\"&gt;Password&lt;/label&gt;\n            &lt;input type=\"password\" class=\"form-control\" id=\"password\" name=\"password\" aria-describedby=\"passwordHelp\" placeholder=\"Enter password\" wire:model.defer=\"password\"&gt;\n            @error(\'password\')&lt;small id=\"passwordHelp-php\" class=\"form-text text-danger\"&gt;{{ $message }}&lt;/small&gt;@enderror\n            &lt;small id=\"passwordHelp-js\" class=\"form-text text-danger\"&gt;&lt;/small&gt;\n        &lt;/div&gt;\n\n        &lt;div class=\"form-group mb-3\"&gt;\n            &lt;label for=\"password_confirmation\" class=\"form-label\"&gt;Password Confirmation&lt;/label&gt;\n            &lt;input type=\"password\" class=\"form-control\" id=\"password_confirmation\" name=\"password_confirmation\" aria-describedby=\"password_confirmationHelp\" placeholder=\"Enter password confirmation\" wire:model.defer=\"password_confirmation\"&gt;\n            @error(\'password_confirmation\')&lt;small id=\"password_confirmationHelp-php\" class=\"form-text text-danger\"&gt;{{ $message }}&lt;/small&gt;@enderror\n            &lt;small id=\"password_confirmationHelp-js\" class=\"form-text text-danger\"&gt;&lt;/small&gt;\n        &lt;/div&gt;\n\n        &lt;div class=\"form-group\"&gt;\n            &lt;button type=\"button\" class=\"btn btn-primary float-end\" wire:click=\"submit\"&gt;Add&lt;/button&gt;\n        &lt;/div&gt;\n    &lt;/form&gt;</code></pre>\n\n<pre>\n<code class=\"language-javascript\">$(document).ready(function () {\n\n    $(\'#name\').keyup(function () {\n        $(\'#nameHelp-php\').html(\'\')\n        let val = $(this).val().trim()\n        if (val === \'\')\n        {\n            $(\'#nameHelp-js\').html(\'The name field is required.\')\n        }\n        else if (val.length &lt; 3)\n        {\n            $(\'#nameHelp-js\').html(\'The name must be at least 3 characters.\')\n        }\n        else if (val.length &gt; 255)\n        {\n            $(\'#nameHelp-js\').html(\'The name must not be greater than 255 characters.\')\n        }\n        else\n        {\n            $(\'#nameHelp-js\').html(\'\')\n        }\n    })\n\n    $(\'#email\').keyup(function () {\n        $(\'#emailHelp-php\').html(\'\')\n        let val = $(this).val().trim()\n        if (val === \'\')\n        {\n            $(\'#emailHelp-js\').html(\'The email field is required.\')\n        }\n        else if (!validateEmail(val))\n        {\n            $(\'#emailHelp-js\').html(\'The email must be a valid email address.\\n\')\n        }\n        else if (val.length &gt; 255)\n        {\n            $(\'#emailHelp-js\').html(\'The email must not be greater than 255 characters.\')\n        }\n        else\n        {\n            $(\'#emailHelp-js\').html(\'\')\n        }\n    })\n\n    $(\'#password\').keyup(function () {\n        $(\'#passwordHelp-php\').html(\'\')\n        let val = $(this).val().trim()\n        if (val === \'\')\n        {\n            $(\'#passwordHelp-js\').html(\'The password field is required.\')\n        }\n        else if (val.length &lt; 8)\n        {\n            $(\'#passwordHelp-js\').html(\'The password must be at least 8 characters.\')\n        }\n        else if (val.length &gt; 255)\n        {\n            $(\'#passwordHelp-js\').html(\'The password must not be greater than 255 characters.\')\n        }\n        else if (!val.match(/[A-Z]/))\n        {\n            $(\'#passwordHelp-js\').html(\'The password must contain at least one uppercase character.\')\n        }\n        else if (!specialCharacter(val))\n        {\n            $(\'#passwordHelp-js\').html(\'The password must contain one special character.\')\n        }\n        else if (val !== $(\'#password_confirmation\').val())\n        {\n            $(\'#passwordHelp-js\').html(\'The password and password confirmation must match.\')\n        }\n        else\n        {\n            $(\'#passwordHelp-js\').html(\'\')\n        }\n    })\n\n    $(\'#password_confirmation\').keyup(function () {\n        $(\'#password_confirmationHelp-php\').html(\'\')\n        let val = $(this).val().trim()\n        if (val === \'\')\n        {\n            $(\'#password_confirmationHelp-js\').html(\'The password confirmation field is required.\')\n        }\n        else if (val.length &lt; 8)\n        {\n            $(\'#password_confirmationHelp-js\').html(\'The password confirmation must be at least 8 characters.\')\n        }\n        else\n        {\n            $(\'#password_confirmationHelp-js\').html(\'\')\n        }\n    })\n\n    function validateEmail(emailAddress)\n    {\n        var emailReg = /^([\\w-\\.]+@([\\w-]+\\.)+[\\w-]{2,4})?$/;\n        return emailReg.test(emailAddress);\n    }\n\n    function specialCharacter(password)\n    {\n        var passReg = /[^\\w\\s]/gi;\n        return passReg.test(password);\n    }\n})\n</code></pre>\n\n<p>&nbsp;</p>', '<p>&nbsp;&nbsp;</p>\n\n<pre>\n<code class=\"language-html\">&lt;form action=\"\" id=\"application-form\" method=\"post\" autocomplete=\"off\" enctype=\"multipart/form-data\"&gt;\n        @csrf\n        &lt;div class=\"form-group mb-3\"&gt;\n            &lt;label for=\"name\" class=\"form-label\"&gt;Name&lt;/label&gt;\n            &lt;input type=\"text\" class=\"form-control\" id=\"name\" name=\"name\" aria-describedby=\"nameHelp\" placeholder=\"Enter name\" wire:model.defer=\"name\"&gt;\n            @error(\'name\')&lt;small id=\"nameHelp-php\" class=\"form-text text-danger\"&gt;{{ $message }}&lt;/small&gt;@enderror\n            &lt;small id=\"nameHelp-js\" class=\"form-text text-danger\"&gt;&lt;/small&gt;\n        &lt;/div&gt;\n\n        &lt;div class=\"form-group mb-3\"&gt;\n            &lt;label for=\"email\" class=\"form-label\"&gt;Email&lt;/label&gt;\n            &lt;input type=\"text\" class=\"form-control\" id=\"email\" name=\"email\" aria-describedby=\"emailHelp\" placeholder=\"Enter email\" wire:model.defer=\"email\"&gt;\n            @error(\'email\')&lt;small id=\"emailHelp-php\" class=\"form-text text-danger\"&gt;{{ $message }}&lt;/small&gt;@enderror\n            &lt;small id=\"emailHelp-js\" class=\"form-text text-danger\"&gt;&lt;/small&gt;\n        &lt;/div&gt;\n\n        &lt;div class=\"form-group mb-3\"&gt;\n            &lt;label for=\"password\" class=\"form-label\"&gt;Password&lt;/label&gt;\n            &lt;input type=\"password\" class=\"form-control\" id=\"password\" name=\"password\" aria-describedby=\"passwordHelp\" placeholder=\"Enter password\" wire:model.defer=\"password\"&gt;\n            @error(\'password\')&lt;small id=\"passwordHelp-php\" class=\"form-text text-danger\"&gt;{{ $message }}&lt;/small&gt;@enderror\n            &lt;small id=\"passwordHelp-js\" class=\"form-text text-danger\"&gt;&lt;/small&gt;\n        &lt;/div&gt;\n\n        &lt;div class=\"form-group mb-3\"&gt;\n            &lt;label for=\"password_confirmation\" class=\"form-label\"&gt;Password Confirmation&lt;/label&gt;\n            &lt;input type=\"password\" class=\"form-control\" id=\"password_confirmation\" name=\"password_confirmation\" aria-describedby=\"password_confirmationHelp\" placeholder=\"Enter password confirmation\" wire:model.defer=\"password_confirmation\"&gt;\n            @error(\'password_confirmation\')&lt;small id=\"password_confirmationHelp-php\" class=\"form-text text-danger\"&gt;{{ $message }}&lt;/small&gt;@enderror\n            &lt;small id=\"password_confirmationHelp-js\" class=\"form-text text-danger\"&gt;&lt;/small&gt;\n        &lt;/div&gt;\n\n        &lt;div class=\"form-group\"&gt;\n            &lt;button type=\"button\" class=\"btn btn-primary float-end\" wire:click=\"submit\"&gt;Add&lt;/button&gt;\n        &lt;/div&gt;\n    &lt;/form&gt;</code></pre>\n\n<pre>\n<code class=\"language-javascript\">$(document).ready(function () {\n\n    $(\'#name\').keyup(function () {\n        $(\'#nameHelp-php\').html(\'\')\n        let val = $(this).val().trim()\n        if (val === \'\')\n        {\n            $(\'#nameHelp-js\').html(\'The name field is required.\')\n        }\n        else if (val.length &lt; 3)\n        {\n            $(\'#nameHelp-js\').html(\'The name must be at least 3 characters.\')\n        }\n        else if (val.length &gt; 255)\n        {\n            $(\'#nameHelp-js\').html(\'The name must not be greater than 255 characters.\')\n        }\n        else\n        {\n            $(\'#nameHelp-js\').html(\'\')\n        }\n    })\n\n    $(\'#email\').keyup(function () {\n        $(\'#emailHelp-php\').html(\'\')\n        let val = $(this).val().trim()\n        if (val === \'\')\n        {\n            $(\'#emailHelp-js\').html(\'The email field is required.\')\n        }\n        else if (!validateEmail(val))\n        {\n            $(\'#emailHelp-js\').html(\'The email must be a valid email address.\\n\')\n        }\n        else if (val.length &gt; 255)\n        {\n            $(\'#emailHelp-js\').html(\'The email must not be greater than 255 characters.\')\n        }\n        else\n        {\n            $(\'#emailHelp-js\').html(\'\')\n        }\n    })\n\n    $(\'#password\').keyup(function () {\n        $(\'#passwordHelp-php\').html(\'\')\n        let val = $(this).val().trim()\n        if (val === \'\')\n        {\n            $(\'#passwordHelp-js\').html(\'The password field is required.\')\n        }\n        else if (val.length &lt; 8)\n        {\n            $(\'#passwordHelp-js\').html(\'The password must be at least 8 characters.\')\n        }\n        else if (val.length &gt; 255)\n        {\n            $(\'#passwordHelp-js\').html(\'The password must not be greater than 255 characters.\')\n        }\n        else if (!val.match(/[A-Z]/))\n        {\n            $(\'#passwordHelp-js\').html(\'The password must contain at least one uppercase character.\')\n        }\n        else if (!specialCharacter(val))\n        {\n            $(\'#passwordHelp-js\').html(\'The password must contain one special character.\')\n        }\n        else if (val !== $(\'#password_confirmation\').val())\n        {\n            $(\'#passwordHelp-js\').html(\'The password and password confirmation must match.\')\n        }\n        else\n        {\n            $(\'#passwordHelp-js\').html(\'\')\n        }\n    })\n\n    $(\'#password_confirmation\').keyup(function () {\n        $(\'#password_confirmationHelp-php\').html(\'\')\n        let val = $(this).val().trim()\n        if (val === \'\')\n        {\n            $(\'#password_confirmationHelp-js\').html(\'The password confirmation field is required.\')\n        }\n        else if (val.length &lt; 8)\n        {\n            $(\'#password_confirmationHelp-js\').html(\'The password confirmation must be at least 8 characters.\')\n        }\n        else\n        {\n            $(\'#password_confirmationHelp-js\').html(\'\')\n        }\n    })\n\n    function validateEmail(emailAddress)\n    {\n        var emailReg = /^([\\w-\\.]+@([\\w-]+\\.)+[\\w-]{2,4})?$/;\n        return emailReg.test(emailAddress);\n    }\n\n    function specialCharacter(password)\n    {\n        var passReg = /[^\\w\\s]/gi;\n        return passReg.test(password);\n    }\n})\n</code></pre>\n\n<p>&nbsp;</p>', 6, 0, '2021-04-11 16:16:38', '2021-04-11 16:16:38'),
(21, 'fwrite(): send of 18 bytes failed with errno=10054 An existing connection was forcibly closed by the remote host.', 'fwrite(): send of 18 bytes failed with errno=10054 An existing connection was forcibly closed by the remote host.', 'fwrite-send-of-18-bytes-failed-with-errno10054-an-existing-connection-was-forcibly-closed-by-the-remote-host', 'fwrite-send-of-18-bytes-failed-with-errno10054-an-existing-connection-was-forcibly-closed-by-the-remote-host', '<p>When sending an email with Mailjet,&nbsp;I was getting an error&nbsp;&nbsp;<span style=\"font-size:16px\"><span style=\"color:#c0392b\">&#39;fwrite (): send 18 bytes failed with errno = 10054 An existing connection was forcibly closed by the remote host.&#39;</span></span> . To solve this problem, <span style=\"font-size:16px\"><span style=\"color:#27ae60\">I simply changed the php.ini file to smtp_port = 25 to smtp_port = 587</span></span></p>\n\n<pre>\n<code class=\"language-ini\">[mail function]\n; For Win32 only.\n; http://php.net/smtp\nSMTP = localhost\n; http://php.net/smtp-port\nsmtp_port = 587</code></pre>\n\n<p>&nbsp;</p>', '<p>Mailjet ilə email g&ouml;ndərərkən <span style=\"font-size:16px\"><span style=\"color:#c0392b\">&#39;fwrite(): send of 18 bytes failed with errno=10054 An existing connection was forcibly closed by the remote host.&#39;</span></span> xeta alırdım.<span style=\"font-size:16px\"><span style=\"color:#27ae60\">Bu problemi həll etmək &uuml;&ccedil;&uuml;n sadəcə php.ini faylından smtp_port &nbsp;= 25 - i smtp_port = 587 -ə dəyişdim.</span></span></p>\n\n<pre>\n<code class=\"language-ini\">[mail function]\n; For Win32 only.\n; http://php.net/smtp\nSMTP = localhost\n; http://php.net/smtp-port\nsmtp_port = 587</code></pre>\n\n<p><br />\n&nbsp;</p>', 5, 0, '2021-04-13 15:35:29', '2021-04-13 15:38:54'),
(22, 'How to Automatically Generate Sitemap in Laravel?', 'Laravel-də avtomatik olaraq sitemap  necə yaratmaq olar?', 'how-to-automatically-generate-sitemap-in-laravel', 'laravel-de-avtomatik-olaraq-sitemap-nece-yaratmaq-olar', '<ol>\n	<li>First create a route in web.php:\n	<pre>\n<code class=\"language-php\">// Sitemap.xml\nRoute::get(\'sitemap-generate\',[sitemapController::class,\'index\'])\n    -&gt;name(\'sitemap.generate\');</code></pre>\n	</li>\n	<li>Run the command <span style=\"color:#27ae60\"><span style=\"font-size:16px\">php artisan make:controller sitemapController&nbsp;</span></span>\n	<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Http\\Controllers;\n\nuse App\\Models\\AlternativeSlug;\nuse App\\Models\\Blog;\nuse App\\Models\\Category;\nuse Illuminate\\Support\\Facades\\File;\n\nclass sitemapController extends Controller\n{\n    public function index()\n    {\n        // All blogs\n        $blogs = Blog::pluck(\'slug\')-&gt;toArray();\n\n        $blog_slug = array_map(function ($slug) {\n            return \'\n        &lt;url&gt;\n            &lt;loc&gt;\'.route(\'front.single.blog\',$slug).\'&lt;/loc&gt;\n            &lt;lastmod&gt;\'.date(\'Y-m-d\').\'&lt;/lastmod&gt;\n            &lt;changefreq&gt;weekly&lt;/changefreq&gt;\n            &lt;priority&gt;0.9&lt;/priority&gt;\n        &lt;/url&gt;\n        \';\n        }, $blogs);\n\n        // All Alternative slugs\n        $alternative_slug = AlternativeSlug::pluck(\'slug\')-&gt;toArray();\n\n        $alternative_slug = array_map(function ($slug) {\n            return \'\n        &lt;url&gt;\n            &lt;loc&gt;\'.route(\'front.single.blog\',$slug).\'&lt;/loc&gt;\n            &lt;lastmod&gt;\'.date(\'Y-m-d\').\'&lt;/lastmod&gt;\n            &lt;changefreq&gt;weekly&lt;/changefreq&gt;\n            &lt;priority&gt;0.9&lt;/priority&gt;\n        &lt;/url&gt;\n        \';\n        }, $alternative_slug);\n\n        // All Categories\n        $categories_slug = Category::pluck(\'slug\')-&gt;toArray();\n\n        $categories_slug = array_map(function ($slug) {\n            return \'\n        &lt;url&gt;\n            &lt;loc&gt;\'.route(\'front.blog.category\',$slug).\'&lt;/loc&gt;\n            &lt;lastmod&gt;\'.date(\'Y-m-d\').\'&lt;/lastmod&gt;\n            &lt;changefreq&gt;weekly&lt;/changefreq&gt;\n            &lt;priority&gt;0.9&lt;/priority&gt;\n        &lt;/url&gt;\n        \';\n        }, $categories_slug);\n\n        $data = \'&lt;urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\"&gt;\';\n\n        // Front homepage\n        $data .= \'\n        &lt;url&gt;\n            &lt;loc&gt;\'.route(\'front.index\').\'&lt;/loc&gt;\n            &lt;lastmod&gt;\'.date(\'Y-m-d\').\'&lt;/lastmod&gt;\n            &lt;changefreq&gt;weekly&lt;/changefreq&gt;\n            &lt;priority&gt;0.9&lt;/priority&gt;\n        &lt;/url&gt;\n        \';\n\n        // Login view\n        $data .= \'\n        &lt;url&gt;\n            &lt;loc&gt;\'.route(\'login\').\'&lt;/loc&gt;\n            &lt;lastmod&gt;\'.date(\'Y-m-d\').\'&lt;/lastmod&gt;\n            &lt;changefreq&gt;weekly&lt;/changefreq&gt;\n            &lt;priority&gt;0.9&lt;/priority&gt;\n        &lt;/url&gt;\n        \';\n\n        // Logout\n        $data .= \'\n        &lt;url&gt;\n            &lt;loc&gt;\'.route(\'logout\').\'&lt;/loc&gt;\n            &lt;lastmod&gt;\'.date(\'Y-m-d\').\'&lt;/lastmod&gt;\n            &lt;changefreq&gt;weekly&lt;/changefreq&gt;\n            &lt;priority&gt;0.9&lt;/priority&gt;\n        &lt;/url&gt;\n        \';\n\n        // Front About us\n        $data .= \'\n        &lt;url&gt;\n            &lt;loc&gt;\'.route(\'front.about\').\'&lt;/loc&gt;\n            &lt;lastmod&gt;\'.date(\'Y-m-d\').\'&lt;/lastmod&gt;\n            &lt;changefreq&gt;weekly&lt;/changefreq&gt;\n            &lt;priority&gt;0.9&lt;/priority&gt;\n        &lt;/url&gt;\n        \';\n\n        // Contact\n        $data .= \'\n        &lt;url&gt;\n            &lt;loc&gt;\'.route(\'front.contact\').\'&lt;/loc&gt;\n            &lt;lastmod&gt;\'.date(\'Y-m-d\').\'&lt;/lastmod&gt;\n            &lt;changefreq&gt;weekly&lt;/changefreq&gt;\n            &lt;priority&gt;0.9&lt;/priority&gt;\n        &lt;/url&gt;\n        \';\n\n        // Front Blog\n        $data .= \'\n        &lt;url&gt;\n            &lt;loc&gt;\'.route(\'front.blogs\').\'&lt;/loc&gt;\n            &lt;lastmod&gt;\'.date(\'Y-m-d\').\'&lt;/lastmod&gt;\n            &lt;changefreq&gt;weekly&lt;/changefreq&gt;\n            &lt;priority&gt;0.9&lt;/priority&gt;\n        &lt;/url&gt;\n        \';\n\n        // Front Single Blog\n        $data .= implode(\' \',$blog_slug);\n\n        $data .= implode(\' \',$alternative_slug);\n\n        $data .= implode(\' \',$categories_slug);\n\n        $data .= \'&lt;/urlset&gt;\';\n        File::put(public_path(\'sitemap.xml\'), $data);\n\n        return redirect(config(\'app.url\').\'/sitemap.xml\');\n    }\n}\n</code></pre>\n\n	<p>&nbsp;</p>\n	</li>\n</ol>', '<ol>\n	<li>&nbsp;Birinci web.php -də route yaradırıq:\n	<pre>\n<code class=\"language-php\">// Sitemap.xml\nRoute::get(\'sitemap-generate\',[sitemapController::class,\'index\'])\n    -&gt;name(\'sitemap.generate\');</code></pre>\n	</li>\n	<li><span style=\"font-size:16px\">php artisan make:controller sitemapController </span>əmrini &ccedil;alışdırırıq<span style=\"font-size:16px\">&nbsp;</span>\n	<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Http\\Controllers;\n\nuse App\\Models\\AlternativeSlug;\nuse App\\Models\\Blog;\nuse App\\Models\\Category;\nuse Illuminate\\Support\\Facades\\File;\n\nclass sitemapController extends Controller\n{\n    public function index()\n    {\n        // All blogs\n        $blogs = Blog::pluck(\'slug\')-&gt;toArray();\n\n        $blog_slug = array_map(function ($slug) {\n            return \'\n        &lt;url&gt;\n            &lt;loc&gt;\'.route(\'front.single.blog\',$slug).\'&lt;/loc&gt;\n            &lt;lastmod&gt;\'.date(\'Y-m-d\').\'&lt;/lastmod&gt;\n            &lt;changefreq&gt;weekly&lt;/changefreq&gt;\n            &lt;priority&gt;0.9&lt;/priority&gt;\n        &lt;/url&gt;\n        \';\n        }, $blogs);\n\n        // All Alternative slugs\n        $alternative_slug = AlternativeSlug::pluck(\'slug\')-&gt;toArray();\n\n        $alternative_slug = array_map(function ($slug) {\n            return \'\n        &lt;url&gt;\n            &lt;loc&gt;\'.route(\'front.single.blog\',$slug).\'&lt;/loc&gt;\n            &lt;lastmod&gt;\'.date(\'Y-m-d\').\'&lt;/lastmod&gt;\n            &lt;changefreq&gt;weekly&lt;/changefreq&gt;\n            &lt;priority&gt;0.9&lt;/priority&gt;\n        &lt;/url&gt;\n        \';\n        }, $alternative_slug);\n\n        // All Categories\n        $categories_slug = Category::pluck(\'slug\')-&gt;toArray();\n\n        $categories_slug = array_map(function ($slug) {\n            return \'\n        &lt;url&gt;\n            &lt;loc&gt;\'.route(\'front.blog.category\',$slug).\'&lt;/loc&gt;\n            &lt;lastmod&gt;\'.date(\'Y-m-d\').\'&lt;/lastmod&gt;\n            &lt;changefreq&gt;weekly&lt;/changefreq&gt;\n            &lt;priority&gt;0.9&lt;/priority&gt;\n        &lt;/url&gt;\n        \';\n        }, $categories_slug);\n\n        $data = \'&lt;urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\"&gt;\';\n\n        // Front homepage\n        $data .= \'\n        &lt;url&gt;\n            &lt;loc&gt;\'.route(\'front.index\').\'&lt;/loc&gt;\n            &lt;lastmod&gt;\'.date(\'Y-m-d\').\'&lt;/lastmod&gt;\n            &lt;changefreq&gt;weekly&lt;/changefreq&gt;\n            &lt;priority&gt;0.9&lt;/priority&gt;\n        &lt;/url&gt;\n        \';\n\n        // Login view\n        $data .= \'\n        &lt;url&gt;\n            &lt;loc&gt;\'.route(\'login\').\'&lt;/loc&gt;\n            &lt;lastmod&gt;\'.date(\'Y-m-d\').\'&lt;/lastmod&gt;\n            &lt;changefreq&gt;weekly&lt;/changefreq&gt;\n            &lt;priority&gt;0.9&lt;/priority&gt;\n        &lt;/url&gt;\n        \';\n\n        // Logout\n        $data .= \'\n        &lt;url&gt;\n            &lt;loc&gt;\'.route(\'logout\').\'&lt;/loc&gt;\n            &lt;lastmod&gt;\'.date(\'Y-m-d\').\'&lt;/lastmod&gt;\n            &lt;changefreq&gt;weekly&lt;/changefreq&gt;\n            &lt;priority&gt;0.9&lt;/priority&gt;\n        &lt;/url&gt;\n        \';\n\n        // Front About us\n        $data .= \'\n        &lt;url&gt;\n            &lt;loc&gt;\'.route(\'front.about\').\'&lt;/loc&gt;\n            &lt;lastmod&gt;\'.date(\'Y-m-d\').\'&lt;/lastmod&gt;\n            &lt;changefreq&gt;weekly&lt;/changefreq&gt;\n            &lt;priority&gt;0.9&lt;/priority&gt;\n        &lt;/url&gt;\n        \';\n\n        // Contact\n        $data .= \'\n        &lt;url&gt;\n            &lt;loc&gt;\'.route(\'front.contact\').\'&lt;/loc&gt;\n            &lt;lastmod&gt;\'.date(\'Y-m-d\').\'&lt;/lastmod&gt;\n            &lt;changefreq&gt;weekly&lt;/changefreq&gt;\n            &lt;priority&gt;0.9&lt;/priority&gt;\n        &lt;/url&gt;\n        \';\n\n        // Front Blog\n        $data .= \'\n        &lt;url&gt;\n            &lt;loc&gt;\'.route(\'front.blogs\').\'&lt;/loc&gt;\n            &lt;lastmod&gt;\'.date(\'Y-m-d\').\'&lt;/lastmod&gt;\n            &lt;changefreq&gt;weekly&lt;/changefreq&gt;\n            &lt;priority&gt;0.9&lt;/priority&gt;\n        &lt;/url&gt;\n        \';\n\n        // Front Single Blog\n        $data .= implode(\' \',$blog_slug);\n\n        $data .= implode(\' \',$alternative_slug);\n\n        $data .= implode(\' \',$categories_slug);\n\n        $data .= \'&lt;/urlset&gt;\';\n        File::put(public_path(\'sitemap.xml\'), $data);\n\n        return redirect(config(\'app.url\').\'/sitemap.xml\');\n    }\n}\n</code></pre>\n	</li>\n	<br />\n	&nbsp;\n</ol>', 5, 0, '2021-04-14 11:58:20', '2021-04-14 11:58:20'),
(23, 'How to Export CSV file in Laravel', 'CSV faylını Laravel-də necə ixrac etmək olar', 'how-to-export-csv-file-in-laravel', 'csv-faylini-laravel-de-nece-ixrac-etmek-olar', '<p>In Laravel projects export csv and excel file from database more required. In project we require to export the rows from the database in laravel but I checked in google more then sites utilizing library but if we engender csv utilizing php function then why we utilize any package. So guys lets start to export CSV Data in laravel example utilizing facile steps.</p>\n\n<p>In first step you require to integrate a route in your web.php file.</p>\n\n<p><span style=\"font-size:14px\"><strong>Step 1: Add Route</strong></span></p>\n\n<pre>\n<code class=\"language-php\">// Subscribe export to csv\n    Route::get(\'subscribe-export-csv\',[subscribeController::class,\'subscriberExportCsv\'])\n        -&gt;name(\'admin.subscribe.export.csv\');</code></pre>\n\n<p><span style=\"font-size:14px\"><strong>Step 2: In Blade File</strong></span></p>\n\n<p>Add export button link in your blade file from where you want to export your subscribers.</p>\n\n<pre>\n<code class=\"language-html\">&lt;span data-href=\"{{ route(\'admin.subscribe.export.csv\') }}\" id=\"export\" class=\"btn btn-success w-5 mb-1\" onclick=\"exportSubscribers(event.target);\"&gt;CSV&lt;/span&gt;</code></pre>\n\n<p><span style=\"font-size:14px\"><strong>Step 3: In Js file</strong></span></p>\n\n<p>In this step add a export function in you js file to exporting data.</p>\n\n<pre>\n<code class=\"language-javascript\">&lt;script&gt;\n    function exportSubscribers(_this) {\n       let _url = $(_this).data(\'href\');\n       window.location.href = _url;\n    }\n&lt;/script&gt;</code></pre>\n\n<p><span style=\"font-size:14px\"><strong>Step 4: In your Controller&nbsp;</strong></span><br />\nIn last step you need to add a function to export rows in csv in laravel application. Here we get all subscribers but you can modify your code which you want to export you can add in column and subscribers.</p>\n\n<pre>\n<code class=\"language-php\">public function subscriberExportCsv(Request $request)\n{\n    $fileName = \'subscribers\'.date(\'-Y-m-d-h-i-s\').\'.csv\';\n    $subscribers = Subscribers::all();\n\n    $headers = array(\n        \"Content-type\"        =&gt; \"text/csv\",\n        \"Content-Disposition\" =&gt; \"attachment; filename=$fileName\",\n        \"Pragma\"              =&gt; \"no-cache\",\n        \"Cache-Control\"       =&gt; \"must-revalidate, post-check=0, pre-check=0\",\n        \"Expires\"             =&gt; \"0\"\n    );\n\n    $columns = array(\'Email\', \'Verify\', \'Date\');\n\n    $callback = function() use($subscribers, $columns) {\n        $file = fopen(\'php://output\', \'w\');\n        fputcsv($file, $columns);\n\n        foreach ($subscribers as $subscriber) {\n            $row[\'email\']  = $subscriber-&gt;email;\n            $row[\'verify\']  = $subscriber-&gt;verify === 1 ? \'verified\' : \'not verified\';\n            $row[\'updated_at\']    = $subscriber-&gt;updated_at;\n\n            fputcsv($file, array($row[\'email\'], $row[\'verify\'], $row[\'updated_at\']));\n        }\n\n        fclose($file);\n    };\n\n    return response()-&gt;stream($callback, 200, $headers);\n}</code></pre>\n\n<p>&nbsp;</p>', '<p>Laravel layihələrində verilənlər bazasından verilənləri csv və excel faylları kimi&nbsp;ixrac etmək daha &ccedil;ox tələb olunur.Ancaq google-da kitabxanadan istifadə edən saytlara daha &ccedil;ox rast gəldim, lakin php funksiyasından istifadə edərək verilənləri CSV faylı kimi ixrac etsək, niyə hər hansı bir paketdən istifadə edirik. Beləliklə, uşaqlar verilənləri CSV faylı kimi necə ixrac etmək lazım olduğunu aşağıdakı laravel n&uuml;munəsində birlikdə baxaq.</p>\n\n<p>İlk addımda bir route -u web.php faylınıza inteqrasiya etməlisiniz.</p>\n\n<p><span style=\"font-size:14px\"><strong>Addım 1: Route əlavə edin</strong></span></p>\n\n<pre>\n<code class=\"language-php\">// Subscribe export to csv\n    Route::get(\'subscribe-export-csv\',[subscribeController::class,\'subscriberExportCsv\'])\n        -&gt;name(\'admin.subscribe.export.csv\');</code></pre>\n\n<p><span style=\"font-size:14px\"><strong>Addım 2: Blade Faylında</strong></span><br />\nAbunə&ccedil;iləri ixrac etmək istədiyiniz yerdə&nbsp;blade faylınıza ixrac d&uuml;yməsinə əlavə edin.</p>\n\n<pre>\n<code class=\"language-html\">&lt;span data-href=\"{{ route(\'admin.subscribe.export.csv\') }}\" id=\"export\" class=\"btn btn-success w-5 mb-1\" onclick=\"exportSubscribers(event.target);\"&gt;CSV&lt;/span&gt;</code></pre>\n\n<p><span style=\"font-size:14px\"><strong>Adım 3: Js faylında</strong></span><br />\nBu addımda, js faylında ixrac &uuml;&ccedil;&uuml;n bir y&ouml;nləndirmə edin.</p>\n\n<pre>\n<code class=\"language-javascript\">&lt;script&gt;\n    function exportSubscribers(_this) {\n       let _url = $(_this).data(\'href\');\n       window.location.href = _url;\n    }\n&lt;/script&gt;</code></pre>\n\n<p><span style=\"font-size:14px\"><strong>Addım 4: Kontrollerinizdə</strong></span><br />\nSon addımda laravel tətbiqində CSV-də verilənləri ixrac etmək &uuml;&ccedil;&uuml;n bir funksiya əlavə etməlisiniz. Burada b&uuml;t&uuml;n abunə&ccedil;iləri əldə edirik, ancaq ixrac etmək istədiyiniz cədvəli dəyişə bilərsiniz.</p>\n\n<pre>\n<code class=\"language-php\">public function subscriberExportCsv(Request $request)\n{\n    $fileName = \'subscribers\'.date(\'-Y-m-d-h-i-s\').\'.csv\';\n    $subscribers = Subscribers::all();\n\n    $headers = array(\n        \"Content-type\"        =&gt; \"text/csv\",\n        \"Content-Disposition\" =&gt; \"attachment; filename=$fileName\",\n        \"Pragma\"              =&gt; \"no-cache\",\n        \"Cache-Control\"       =&gt; \"must-revalidate, post-check=0, pre-check=0\",\n        \"Expires\"             =&gt; \"0\"\n    );\n\n    $columns = array(\'Email\', \'Verify\', \'Date\');\n\n    $callback = function() use($subscribers, $columns) {\n        $file = fopen(\'php://output\', \'w\');\n        fputcsv($file, $columns);\n\n        foreach ($subscribers as $subscriber) {\n            $row[\'email\']  = $subscriber-&gt;email;\n            $row[\'verify\']  = $subscriber-&gt;verify === 1 ? \'verified\' : \'not verified\';\n            $row[\'updated_at\']    = $subscriber-&gt;updated_at;\n\n            fputcsv($file, array($row[\'email\'], $row[\'verify\'], $row[\'updated_at\']));\n        }\n\n        fclose($file);\n    };\n\n    return response()-&gt;stream($callback, 200, $headers);\n}</code></pre>\n\n<p>&nbsp;</p>', 5, 0, '2021-04-15 06:30:27', '2021-04-15 06:48:32'),
(24, 'CRUD => DELETE with alert()', 'CRUD => Alertlə silmə işi', 'crud-delete-with-alert', 'crud-alertle-silme-isi', '<pre>\n<code class=\"language-html\">&lt;form class=\"d-inline-block\" action=\"Your url here\" method=\"POST\"&gt;\n	@csrf\n	&lt;input type=\"hidden\" name=\"id\" value=\"{{ $category-&gt;id }}\"&gt;\n	&lt;button class=\"btn btn-sm btn-danger\" type=\"button\" onclick=\"if(confirm(\'Are you sure?\')) $(this).closest(\'form\').submit();\"&gt;Delete&lt;/button&gt;\n&lt;/form&gt;</code></pre>\n\n<p>&nbsp;</p>', '<pre>\n<code class=\"language-html\">&lt;form class=\"d-inline-block\" action=\"Your url here\" method=\"POST\"&gt;\n	@csrf\n	&lt;input type=\"hidden\" name=\"id\" value=\"{{ $category-&gt;id }}\"&gt;\n	&lt;button class=\"btn btn-sm btn-danger\" type=\"button\" onclick=\"if(confirm(\'Are you sure?\')) $(this).closest(\'form\').submit();\"&gt;Delete&lt;/button&gt;\n&lt;/form&gt;</code></pre>\n\n<p>&nbsp;</p>', 5, 0, '2021-04-22 14:23:28', '2021-04-22 14:23:28');
INSERT INTO `blogs` (`id`, `titleEn`, `titleAz`, `slugEn`, `slugAz`, `blogEn`, `blogAz`, `category_id`, `view`, `created_at`, `updated_at`) VALUES
(25, 'How to Setup a Laravel Project You Cloned from Github.com', 'Github.com saytından klonladığınız Laravel Layihəsini necə qurmaq olar', 'how-to-setup-a-laravel-project-you-cloned-from-githubcom', 'githubcom-saytindan-klonladiginiz-laravel-layihesini-nece-qurmaq-olar', '<ol>\n	<li>Clone GitHub repo for this project locally</li>\n	<li>cd into your project</li>\n	<li>Install Composer Dependencies (composer install)</li>\n	<li>cp .env.example .env (cp .env.example .env)</li>\n	<li>php artisan key:generate</li>\n	<li>Create an empty database for our application</li>\n	<li>In the .env file, add database information to allow Laravel to connect to the database</li>\n	<li>php artisan migrate</li>\n	<li>php artisan db:seed (Optional)</li>\n</ol>', '<ol>\n	<li>Clone GitHub repo for this project locally</li>\n	<li>cd into your project</li>\n	<li>Install Composer Dependencies (composer install)</li>\n	<li>cp .env.example .env (cp .env.example .env)</li>\n	<li>php artisan key:generate</li>\n	<li>Create an empty database for our application</li>\n	<li>In the .env file, add database information to allow Laravel to connect to the database</li>\n	<li>php artisan migrate</li>\n	<li>php artisan db:seed (Optional)</li>\n</ol>', 5, 0, '2021-04-25 16:33:41', '2021-04-25 16:45:51'),
(26, 'Mixed Content', 'Mixed Content', 'mixed-content', 'mixed-content', '<pre>\n<code class=\"language-http\">Mixed Content: The page at \'https://www.rahimsuleymanov.com/blog/mixed-content\' was loaded over HTTPS, but requested an insecure stylesheet \'http://fonts.googleapis.com/css?family=Lato:300,400,300italic,400italic\'. This request has been blocked; the content must be served over HTTPS.\n\nMixed Content: The page at \'https://www.rahimsuleymanov.com/blog/mixed-content\' was loaded over HTTPS, but requested an insecure stylesheet \'http://fonts.googleapis.com/css?family=Montserrat:400,700\'. This request has been blocked; the content must be served over HTTPS.</code></pre>\n\n<p>Solution:</p>\n\n<p>Add :&nbsp;&lt;meta http-equiv=&quot;Content-Security-Policy&quot; content=&quot;upgrade-insecure-requests&quot;&gt;</p>', '<p>&nbsp;&nbsp;</p>\n\n<pre>\n<code class=\"language-http\">Mixed Content: The page at \'https://www.rahimsuleymanov.com/blog/mixed-content\' was loaded over HTTPS, but requested an insecure stylesheet \'http://fonts.googleapis.com/css?family=Lato:300,400,300italic,400italic\'. This request has been blocked; the content must be served over HTTPS.\n\nMixed Content: The page at \'https://www.rahimsuleymanov.com/blog/mixed-content\' was loaded over HTTPS, but requested an insecure stylesheet \'http://fonts.googleapis.com/css?family=Montserrat:400,700\'. This request has been blocked; the content must be served over HTTPS.</code></pre>\n\n<p>Əlavə et:&nbsp;&lt;meta http-equiv=&quot;Content-Security-Policy&quot; content=&quot;upgrade-insecure-requests&quot;&gt;</p>', 5, 0, '2021-04-26 19:07:49', '2021-04-26 19:09:23'),
(27, 'Laravel helper package', 'Laravel helper package', 'laravel-helper-package', 'laravel-helper-package', '<pre>\n<code>composer require browner12/helpers</code></pre>\n\n<p>&nbsp;</p>', '<pre>\n<code>composer require browner12/helpers</code></pre>\n\n<p>&nbsp;</p>', 5, 0, '2021-04-28 17:51:46', '2021-04-28 17:51:46'),
(28, 'where and (... OR ...)', 'where and (... OR ...)', 'where-and-or', 'where-and-or', '<pre>\n<code class=\"language-php\">$items = Item::where(\'category_id\',\'=\',$category_id)\n    -&gt;where(\n        fn($query) =&gt; $query\n        -&gt;orWhere(\'name\',\'LIKE\',\'%\'.$search.\'%\')\n        -&gt;orWhere(\'description\',\'LIKE\',\'%\'.$search.\'%\')\n    )\n    -&gt;orderBy($order,$order_type)\n    -&gt;limit(10)\n    -&gt;offset(($page - 1) * 10)\n    -&gt;get();</code></pre>\n\n<p>&nbsp;</p>', '<pre>\n<code class=\"language-php\">$items = Item::where(\'category_id\',\'=\',$category_id)\n    -&gt;where(\n        fn($query) =&gt; $query\n        -&gt;orWhere(\'name\',\'LIKE\',\'%\'.$search.\'%\')\n        -&gt;orWhere(\'description\',\'LIKE\',\'%\'.$search.\'%\')\n    )\n    -&gt;orderBy($order,$order_type)\n    -&gt;limit(10)\n    -&gt;offset(($page - 1) * 10)\n    -&gt;get();</code></pre>\n\n<p>&nbsp;</p>', 5, 0, '2021-05-06 06:52:58', '2021-05-06 06:55:56'),
(29, 'LARAVEL Make the project installable:', 'LARAVEL Proyektin installable halına salınması:', 'laravel-make-the-project-installable', 'laravel-proyektin-installable-halina-salinmasi', '<p><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\"><strong>LARAVEL Make the project installable:<br />\n1.</strong>If you do not release the development version (ie if it is intended for production), then: Packages used for development purposes must first be cleaned. , they should also be thrown into .gitignore.<br />\n<strong>2.</strong>Configure .gitignore file as below:<br />\n/ node_modules</span></span></span></p>\n\n<p><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">.env.backup</span></span></span></p>\n\n<p><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">.phpunit.result.cache</span></span></span></p>\n\n<p><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">docker-compose.override.yml</span></span></span></p>\n\n<p><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">Homestead.json</span></span></span></p>\n\n<p><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">Homestead.yaml</span></span></span></p>\n\n<p><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">npm-debug.log</span></span></span></p>\n\n<p><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">yarn-error.log</span></span></span></p>\n\n<p><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">.idea / *</span></span></span></p>\n\n<p><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">storage / *</span></span></span></p>\n\n<p><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">! storage /&nbsp; framework&nbsp; /&nbsp; cache /&nbsp; index.html</span></span></span></p>\n\n<p><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">! storage /&nbsp; framework&nbsp; /&nbsp; sessions /&nbsp; index.html</span></span></span></p>\n\n<p><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">! storage /&nbsp; framework&nbsp; /&nbsp; views /&nbsp; index.html</span></span></span></p>\n\n<p><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">public /&nbsp; storage /&nbsp; *</span></span></span></p>\n\n<p><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">vendor / *</span></span></span></p>\n\n<p><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">composer.lock</span></span></span></p>\n\n<p><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\"><strong>3.</strong>Create empty index.html file in folders shown below:<br />\nstorage / framework / cache /</span></span></span></p>\n\n<p><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">storage / framework / sessions /</span></span></span></p>\n\n<p><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">storage / framework / views /</span></span></span></p>\n\n<p><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\"><strong>4.</strong>And push to go.</span></span></span></p>', '<p><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\"><strong>LARAVEL Proyektin installable halına salınması:</strong></span></span></span></p>\n\n<p>&nbsp;</p>\n\n<ol>\n	<li style=\"list-style-type:decimal\"><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">Əgər gitə development versiyanı atmırsızsa, (yəni production &uuml;&ccedil;&uuml;n nəzərdə tutmusuzsa o zaman: Development məqsədi ilə istifadə olunan packagelər &ouml;ncə təmizlənməlidir. Məsələn, composer.json-dakı require-dev i&ccedil;indəki packagelər silinməlidi. Composer.json yenilənməlidi. Həm&ccedil;inin əgər development prosesi &uuml;&ccedil;&uuml;n folderlər yaranıbsa, onlar da .gitignore-a atılmalıdır.&nbsp;</span></span></span></li>\n	<li style=\"list-style-type:decimal\"><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">Configure .gitignore file as below:</span></span></span></li>\n</ol>\n\n<p style=\"margin-left:48px\"><span style=\"font-size:14px\"><span style=\"font-family:\'Courier New\'\"><span style=\"color:#080808\"><span style=\"background-color:#ffffff\">/node_modules</span></span></span></span></p>\n\n<p style=\"margin-left:48px\"><span style=\"font-size:14px\"><span style=\"font-family:\'Courier New\'\"><span style=\"color:#080808\"><span style=\"background-color:#ffffff\">.env.backup</span></span></span></span></p>\n\n<p style=\"margin-left:48px\"><span style=\"font-size:14px\"><span style=\"font-family:\'Courier New\'\"><span style=\"color:#080808\"><span style=\"background-color:#ffffff\">.phpunit.result.cache</span></span></span></span></p>\n\n<p style=\"margin-left:48px\"><span style=\"font-size:14px\"><span style=\"font-family:\'Courier New\'\"><span style=\"color:#080808\"><span style=\"background-color:#ffffff\">docker-compose.override.yml</span></span></span></span></p>\n\n<p style=\"margin-left:48px\"><span style=\"font-size:14px\"><span style=\"font-family:\'Courier New\'\"><span style=\"color:#080808\"><span style=\"background-color:#ffffff\">Homestead.json</span></span></span></span></p>\n\n<p style=\"margin-left:48px\"><span style=\"font-size:14px\"><span style=\"font-family:\'Courier New\'\"><span style=\"color:#080808\"><span style=\"background-color:#ffffff\">Homestead.yaml</span></span></span></span></p>\n\n<p style=\"margin-left:48px\"><span style=\"font-size:14px\"><span style=\"font-family:\'Courier New\'\"><span style=\"color:#080808\"><span style=\"background-color:#ffffff\">npm-debug.log</span></span></span></span></p>\n\n<p style=\"margin-left:48px\"><span style=\"font-size:14px\"><span style=\"font-family:\'Courier New\'\"><span style=\"color:#080808\"><span style=\"background-color:#ffffff\">yarn-error.log</span></span></span></span></p>\n\n<p style=\"margin-left:48px\"><span style=\"font-size:14px\"><span style=\"font-family:\'Courier New\'\"><span style=\"color:#080808\"><span style=\"background-color:#ffffff\">.idea/*</span></span></span></span></p>\n\n<p style=\"margin-left:48px\"><span style=\"font-size:14px\"><span style=\"font-family:\'Courier New\'\"><span style=\"color:#080808\"><span style=\"background-color:#ffffff\">storage/*</span></span></span></span></p>\n\n<p style=\"margin-left:48px\"><span style=\"font-size:14px\"><span style=\"font-family:\'Courier New\'\"><span style=\"color:#080808\"><span style=\"background-color:#ffffff\">!storage/framework / cache /index.html</span></span></span></span></p>\n\n<p style=\"margin-left:48px\"><span style=\"font-size:14px\"><span style=\"font-family:\'Courier New\'\"><span style=\"color:#080808\"><span style=\"background-color:#ffffff\">!storage/framework / sessions/ index.html</span></span></span></span></p>\n\n<p style=\"margin-left:48px\"><span style=\"font-size:14px\"><span style=\"font-family:\'Courier New\'\"><span style=\"color:#080808\"><span style=\"background-color:#ffffff\">!storage/framework / views / index.html</span></span></span></span></p>\n\n<p style=\"margin-left:48px\"><span style=\"font-size:14px\"><span style=\"font-family:\'Courier New\'\"><span style=\"color:#080808\"><span style=\"background-color:#ffffff\">public/storage/*</span></span></span></span></p>\n\n<p style=\"margin-left:48px\"><span style=\"font-size:14px\"><span style=\"font-family:\'Courier New\'\"><span style=\"color:#080808\"><span style=\"background-color:#ffffff\">vendor/*</span></span></span></span></p>\n\n<p style=\"margin-left:48px\"><span style=\"font-size:14px\"><span style=\"font-family:\'Courier New\'\"><span style=\"color:#080808\"><span style=\"background-color:#ffffff\">composer.lock</span></span></span></span></p>\n\n<ol start=\"3\">\n	<li style=\"list-style-type:decimal\"><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#000000\">Create empty index.html file in folders shown below:</span></span></span></li>\n</ol>\n\n<p style=\"margin-left:48px\"><span style=\"font-size:14px\"><span style=\"font-family:\'Courier New\'\"><span style=\"color:#080808\"><span style=\"background-color:#ffffff\">storage/framework/cache/</span></span></span></span></p>\n\n<p style=\"margin-left:48px\"><span style=\"font-size:14px\"><span style=\"font-family:\'Courier New\'\"><span style=\"color:#080808\"><span style=\"background-color:#ffffff\">storage/framework/sessions/</span></span></span></span></p>\n\n<p style=\"margin-left:48px\"><span style=\"font-size:14px\"><span style=\"font-family:\'Courier New\'\"><span style=\"color:#080808\"><span style=\"background-color:#ffffff\">storage/framework/views/</span></span></span></span></p>\n\n<ol start=\"4\">\n	<li style=\"list-style-type:decimal\"><span style=\"font-size:14px\"><span style=\"font-family:\'Times New Roman\'\"><span style=\"color:#080808\"><span style=\"background-color:#ffffff\">And push to git.</span></span></span></span></li>\n</ol>', 5, 0, '2021-05-20 10:18:41', '2021-06-17 22:43:42'),
(30, 'Middleware', 'Middleware', 'middleware', 'middleware', '<p>&nbsp;</p>\n\n<pre>\n<code class=\"language-bash\">php artisan make:middleware isMudir</code></pre>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Http\\Middleware;\n\nuse Closure;\nuse Illuminate\\Http\\Request;\nuse Illuminate\\Support\\Facades\\Auth;\n\nclass isMudir\n{\n    /**\n     * Handle an incoming request.\n     *\n     * @param  \\Illuminate\\Http\\Request  $request\n     * @param  \\Closure  $next\n     * @return mixed\n     */\n    public function handle(Request $request, Closure $next)\n    {\n        if (Auth::user() &amp;&amp;  Auth::user()-&gt;vezife_id == 1)\n        {\n            return $next($request);\n        }\n        else\n        {\n            toastr()-&gt;error(\'Sizin bu səhifəyə daxil olmaq icazəniz yoxdur\',\'Xəta\');\n            return redirect()-&gt;route(\'login\');\n        }\n    }\n}\n</code></pre>\n\n<pre>\n<code>App\\Http\\Kernel.php</code></pre>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Http;\n\nuse Illuminate\\Foundation\\Http\\Kernel as HttpKernel;\n\nclass Kernel extends HttpKernel\n{\n\n    /**\n     * The application\'s route middleware.\n     *\n     * These middleware may be assigned to groups or used individually.\n     *\n     * @var array\n     */\n    protected $routeMiddleware = [\n        ...\n        ...\n        ...\n        \'mudir\' =&gt; \\App\\Http\\Middleware\\isMudir::class,\n    ];\n}\n</code></pre>\n\n<p>&nbsp;</p>', '<p>&nbsp;</p>\n\n<pre>\n<code class=\"language-bash\">php artisan make:middleware isMudir</code></pre>\n\n<p>&nbsp;</p>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Http\\Middleware;\n\nuse Closure;\nuse Illuminate\\Http\\Request;\nuse Illuminate\\Support\\Facades\\Auth;\n\nclass isMudir\n{\n    /**\n     * Handle an incoming request.\n     *\n     * @param  \\Illuminate\\Http\\Request  $request\n     * @param  \\Closure  $next\n     * @return mixed\n     */\n    public function handle(Request $request, Closure $next)\n    {\n        if (Auth::user() &amp;&amp;  Auth::user()-&gt;vezife_id == 1)\n        {\n            return $next($request);\n        }\n        else\n        {\n            toastr()-&gt;error(\'Sizin bu səhifəyə daxil olmaq icazəniz yoxdur\',\'Xəta\');\n            return redirect()-&gt;route(\'login\');\n        }\n    }\n}\n</code></pre>\n\n<pre>\n<code>App\\Http\\Kernel.php</code></pre>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Http;\n\nuse Illuminate\\Foundation\\Http\\Kernel as HttpKernel;\n\nclass Kernel extends HttpKernel\n{\n\n    /**\n     * The application\'s route middleware.\n     *\n     * These middleware may be assigned to groups or used individually.\n     *\n     * @var array\n     */\n    protected $routeMiddleware = [\n        ...\n        ...\n        ...\n        \'mudir\' =&gt; \\App\\Http\\Middleware\\isMudir::class,\n    ];\n}\n</code></pre>\n\n<p>&nbsp;</p>', 5, 0, '2021-05-20 13:57:44', '2021-05-20 13:57:44'),
(31, 'Useful links', 'Faydalı linklər', 'useful-links', 'faydali-linkler', '<p><a href=\"https://codingtracker.blogspot.com/\" onclick=\"window.open(this.href, \'RahimSleymanov\', \'resizable=yes,status=yes,location=yes,toolbar=yes,menubar=yes,fullscreen=yes,scrollbars=yes,dependent=yes\'); return false;\">https://codingtracker.blogspot.com/</a></p>', '<p><a href=\"https://codingtracker.blogspot.com/\" onclick=\"window.open(this.href, \'RahimSleymanov\', \'resizable=yes,status=yes,location=yes,toolbar=yes,menubar=yes,fullscreen=yes,scrollbars=yes,dependent=yes\'); return false;\">https://codingtracker.blogspot.com/</a></p>', 11, 0, '2021-06-17 22:39:09', '2021-07-08 12:00:42');
INSERT INTO `blogs` (`id`, `titleEn`, `titleAz`, `slugEn`, `slugAz`, `blogEn`, `blogAz`, `category_id`, `view`, `created_at`, `updated_at`) VALUES
(32, 'Laravel & Yajra (datatables)', 'Laravel & Yajra (datatables)', 'laravel-yajra-datatables', 'laravel-yajra-datatables', '<p>I would like to explain the integration of the Yajra (datatables) library in Laravel on the menu of products I have written for the credit system.</p>\n\n<p>1. First of all, let&#39;s create a folder called Manager, put a layout folder in it and create layout.blade.php in it</p>\n\n<pre>\n<code class=\"language-php\">&lt;!doctype html&gt;\n&lt;html lang=\"en\"&gt;\n&lt;head&gt;\n    &lt;meta charset=\"utf-8\"/&gt;\n    &lt;meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\"/&gt;\n    &lt;meta http-equiv=\"X-UA-Compatible\" content=\"ie=edge\"/&gt;\n    &lt;title&gt;{{ config(\'app.name\') }} - @yield(\'title\')&lt;/title&gt;\n    &lt;link href=\"{{ asset(\'assets/dist/css/tabler.min.css\') }}\" rel=\"stylesheet\"/&gt;\n    &lt;link href=\"{{ asset(\'assets/dist/css/tabler-flags.min.css\') }}\" rel=\"stylesheet\"/&gt;\n    &lt;link href=\"{{ asset(\'assets/dist/css/tabler-payments.min.css\') }}\" rel=\"stylesheet\"/&gt;\n    &lt;link href=\"{{ asset(\'assets/dist/css/tabler-vendors.min.css\') }}\" rel=\"stylesheet\"/&gt;\n    &lt;link href=\"{{ asset(\'assets/dist/css/demo.min.css\') }}\" rel=\"stylesheet\"/&gt;\n    &lt;link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.3/css/all.min.css\" integrity=\"sha512-iBBXm8fW90+nuLcSKlbmrPcLa0OT92xO1BIsZ+ywDWZCvqsWgccV3gFoRBv0z+8dLJgyAHIhR35VZc2oM/gI1w==\" crossorigin=\"anonymous\" /&gt;\n    @toastr_css\n    @yield(\'css\')\n&lt;/head&gt;\n&lt;body class=\"antialiased {{ \\Illuminate\\Support\\Facades\\Cookie::get(\'darkmode\') }}\"&gt;\n&lt;div class=\"page\"&gt;\n    &lt;header class=\"navbar navbar-expand-md navbar-light d-print-none\"&gt;\n        &lt;div class=\"container-xl\"&gt;\n            &lt;button class=\"navbar-toggler\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#navbar-menu\"&gt;\n                &lt;span class=\"navbar-toggler-icon\"&gt;&lt;/span&gt;\n            &lt;/button&gt;\n            &lt;h1 class=\"navbar-brand navbar-brand-autodark d-none-navbar-horizontal pe-0 pe-md-3\"&gt;\n                &lt;a href=\"{{ route(\'mudir.dashboard\') }}\"&gt;\n                    &lt;img src=\"{{ asset(\'assets/dist/logo/logo.png\') }}\" width=\"110\" height=\"32\" alt=\"{{ config(\'app.name\') }}\" class=\"navbar-brand-image\"&gt;\n                &lt;/a&gt;\n            &lt;/h1&gt;\n            &lt;div class=\"navbar-nav flex-row order-md-last\"&gt;\n                &lt;div class=\"nav-item dropdown d-none d-md-flex me-3\"&gt;\n                    &lt;a href=\"#\" class=\"nav-link px-0\" data-bs-toggle=\"dropdown\" tabindex=\"-1\" aria-label=\"Show notifications\"&gt;\n                        &lt;svg xmlns=\"http://www.w3.org/2000/svg\" class=\"icon\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"&gt;&lt;path stroke=\"none\" d=\"M0 0h24v24H0z\" fill=\"none\"/&gt;&lt;path d=\"M10 5a2 2 0 0 1 4 0a7 7 0 0 1 4 6v3a4 4 0 0 0 2 3h-16a4 4 0 0 0 2 -3v-3a7 7 0 0 1 4 -6\" /&gt;&lt;path d=\"M9 17v1a3 3 0 0 0 6 0v-1\" /&gt;&lt;/svg&gt;\n                        &lt;span class=\"badge bg-red\"&gt;&lt;/span&gt;\n                    &lt;/a&gt;\n                    &lt;div class=\"dropdown-menu dropdown-menu-end dropdown-menu-card\"&gt;\n                        &lt;div class=\"card\"&gt;\n                            &lt;div class=\"card-body\"&gt;\n                                Lorem ipsum dolor sit amet, consectetur adipisicing elit. Accusamus ad amet consectetur exercitationem fugiat in ipsa ipsum, natus odio quidem quod repudiandae sapiente. Amet debitis et magni maxime necessitatibus ullam.\n                            &lt;/div&gt;\n                        &lt;/div&gt;\n                    &lt;/div&gt;\n                &lt;/div&gt;\n                &lt;div cl