       });\n        });\n    &lt;/script&gt;\n\n@endsection\n</code></pre>\n\n<p>7)in php file</p>\n\n<pre>\n<code class=\"language-php\">public function show($id)\n{\n    $mehsul = Mehsul::whereId($id)-&gt;first();\n    if ($mehsul === null)\n    {\n        $mehsul = \'tapilmadi\';\n    }\n    else\n    {\n        $mehsul = $mehsul-&gt;kodlasdirilmis_ad;\n    }\n    $mehsul = preg_replace(\'/[^A-Za-z0-9. -]/\', \'\', $mehsul);\n    //$barcode1 = new  DNS1D();\n    $barcode2 = new DNS2D();\n\n    return $barcode2-&gt;getBarcodeHTML($mehsul, \'QRCODE\',3,3);\n}</code></pre>\n\n<p>&nbsp;</p>', '<p>&nbsp;1)<img alt=\"\" src=\"https://rahimsuleymanov.com/images/blogs/1_1629917524.jpeg\" style=\"float:left; width:100%\" /></p>\n\n<p>2)</p>\n\n<p><img alt=\"\" src=\"https://rahimsuleymanov.com/images/blogs/2_1629917606.jpeg\" style=\"float:left; width:100%\" />3)<img alt=\"\" src=\"https://rahimsuleymanov.com/images/blogs/4_1629917643.jpeg\" style=\"float:left; width:100%\" /></p>\n\n<p>4)</p>\n\n<p><img alt=\"\" src=\"https://rahimsuleymanov.com/images/blogs/4_1629917683.jpeg\" style=\"float:left; width:100%\" />5)<img alt=\"\" src=\"https://rahimsuleymanov.com/images/blogs/5_1629917731.jpeg\" style=\"float:left; width:100%\" /></p>\n\n<p>6)html faylda</p>\n\n<pre>\n<code class=\"language-html\">@extends(\'Mudir.layout.master\')\n\n@section(\'title\')\nMəhsullar\n@endsection\n\n@section(\'css\')\n    &lt;link rel=\"stylesheet\" href=\"https://cdn.datatables.net/1.10.22/css/jquery.dataTables.min.css\"&gt;\n    &lt;link rel=\"stylesheet\" href=\"https://cdn.datatables.net/buttons/1.6.5/css/buttons.dataTables.min.css\"&gt;\n    &lt;link rel=\"stylesheet\" href=\"https://cdn.datatables.net/select/1.3.1/css/select.dataTables.min.css\"&gt;\n\n    &lt;style&gt;\n        table tr td {\n            width: max-content !important;\n        }\n\n        table.dataTable {\n            margin: 0 0 !important;\n        }\n\n        .card {\n            word-wrap: normal;\n        }\n\n