(175, 'Latın əlifbası ilə yazılmış mətni necə kiril əlifbasına çevirə bilərəm?', 'Latın əlifbası ilə yazılmış mətni necə kiril əlifbasına çevirə bilərəm?', 'latin-elifbasi-ile-yazilmis-metni-nece-kiril-elifbasina-cevire-bilerem', 'latin-elifbasi-ile-yazilmis-metni-nece-kiril-elifbasina-cevire-bilerem', '<pre>\n<code class=\"language-php\">&lt;?php\n\n/*\n * Latın əlifbası ilə yazılmış mətni necə\n * Kiril əlifbasına çevirə bilərəm?\n */\n\nfunction latinToKiril($inputText): string\n{\n    $latin = [\'a\', \'b\', \'c\', \'ç\', \'d\', \'e\', \'ə\', \'f\', \'g\', \'ğ\', \'h\', \'x\', \'ı\', \'i\', \'j\', \'k\', \'q\', \'l\', \'m\', \'n\', \'o\', \'ö\', \'p\', \'r\', \'s\', \'ş\', \'t\', \'u\', \'ü\', \'v\', \'y\', \'z\'];\n    $cyrillic = [\'а\', \'б\', \'ц\', \'ч\', \'д\', \'е\', \'ә\', \'ф\', \'г\', \'ғ\', \'х\', \'х\', \'ы\', \'и\', \'й\', \'к\', \'г\', \'л\', \'м\', \'н\', \'о\', \'ө\', \'п\', \'р\', \'с\', \'ш\', \'т\', \'у\', \'ү\', \'в\', \'й\', \'з\'];\n\n    return str_replace($latin,$cyrillic,$inputText);\n}\n\n$inputText = \"Salam dünya\";\n\necho latinToKiril($inputText);</code></pre>\n\n<p>&nbsp;</p>', '<pre>\n<code class=\"language-php\">&lt;?php\n\n/*\n * Latın əlifbası ilə yazılmış mətni necə\n * Kiril əlifbasına çevirə bilərəm?\n */\n\nfunction latinToKiril($inputText): string\n{\n    $latin = [\'a\', \'b\', \'c\', \'ç\', \'d\', \'e\', \'ə\', \'f\', \'g\', \'ğ\', \'h\', \'x\', \'ı\', \'i\', \'j\', \'k\', \'q\', \'l\', \'m\', \'n\', \'o\', \'ö\', \'p\', \'r\', \'s\', \'ş\', \'t\', \'u\', \'ü\', \'v\', \'y\', \'z\'];\n    $cyrillic = [\'а\', \'б\', \'ц\', \'ч\', \'д\', \'е\', \'ә\', \'ф\', \'г\', \'ғ\', \'х\', \'х\', \'ы\', \'и\', \'й\', \'к\', \'г\', \'л\', \'м\', \'н\', \'о\', \'ө\', \'п\', \'р\', \'с\', \'ш\', \'т\', \'у\', \'ү\', \'в\', \'й\', \'з\'];\n\n    return str_replace($latin,$cyrillic,$inputText);\n}\n\n$inputText = \"Salam dünya\";\n\necho latinToKiril($inputText);</code></pre>', 4, 0, '2024-01-23 15:41:42', '2024-01-23 15:41:42'),
(176, 'select2 ajax get data', 'select2 ajax get data', 'select2-ajax-get-data', 'select2-ajax-get-data', '<pre>\n<code>web.php faylı</code></pre>\n\n<pre>\n<code class=\"language-php\">Route::get(\'/backend\', [BackendController::class,\'index\'])-&gt;name(\'backend.index\');</code></pre>\n\n<pre>\n<code>BackendController.php faylı</code></pre>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Http\\Controllers;\n\nuse App\\Models\\User;\n\nclass BackendController extends Controller\n{\n    public function index()\n    {\n        $search = \\request(\'term\');\n\n        $query = User::query();\n        if ($search) {\n            $query-&gt;where(\'name\', \'like\', \'%\' . $search . \'%\');\n        }\n\n        $users = $query-&gt;paginate(30);\n\n        return response()-&gt;json($users);\n    }\n}\n</code></pre>\n\n<pre>\n<code>users.blade.php faylı</code></pre>\n\n<pre>\n<code class=\"language-php\">&lt;!DOCTYPE html&gt;\n&lt;html lang=\"en\"&gt;\n&lt;head&gt;\n    &lt;meta charset=\"UTF-8\"&gt;\n    &lt;meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"&gt;\n    &lt;title&gt;Select2 with Laravel and AJAX&lt;/title&gt;\n    &lt;link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/select2/4.0.13/css/select2.min.css\" integrity=\"sha512-nMNlpuaDPrqlEls3IX/Q56H36qvBASwb3ipuo3MxeWbsQB1881ox0cRv7UPTgBlriqoynt35KjEwgGUeUXIPnw==\" crossorigin=\"anonymous\" referrerpolicy=\"no-referrer\" /&gt;\n&lt;/head&gt;\n&lt;body&gt;\n\n&lt;select id=\"mySelect\" style=\"width: 300px;\"&gt;\n    &lt;option value=\"\"&gt;İstifadəçi axtarın...&lt;/option&gt;\n&lt;/select&gt;\n\n&lt;script src=\"https://cdnjs.cloudflare.com/ajax/libs/jquery/3.7.1/jquery.min.js\" integrity=\"sha512-v2CJ7UaYy4JwqLDIrZUI/4hqeoQieOmAZNXBeQyjo21dadnwR+8ZaIJVT8EE2iyI61OV8e6M8PP2/4hpQINQ/g==\" crossorigin=\"anonymous\" referrerpolicy=\"no-referrer\"&gt;&lt;/script&gt;\n&lt;script src=\"https://cdnjs.cloudflare.com/ajax/libs/select2/4.0.13/js/select2.min.js\" integrity=\"sha512-2ImtlRlf2VVmiGZsjm9bEyhjGW4dU7B6TNwh/hx/iSByxNENtj3WVE6o/9Lj4TJeVXPi4bnOIMXFIJJAeufa0A==\" crossorigin=\"anonymous\" referrerpolicy=\"no-referrer\"&gt;&lt;/script&gt;\n&lt;script src=\"https://cdnjs.cloudflare.com/ajax/libs/select2/4.0.13/js/i18n/az.min.js\" integrity=\"sha512-5h/4MstAOhpL8LHF6e7tTEv31xdr5wY7JL9w7nqOI2zs/tL1ofuRfX+g+RwJ7l/3xc5cIAeLMLne6m+QYX67hg==\" crossorigin=\"anonymous\" referrerpolicy=\"no-referrer\"&gt;&lt;/script&gt;\n&lt;script&gt;\n    $(document).ready(function() {\n        $(\'#mySelect\').select2({\n            language: \"az\",\n            ajax: {\n                url: \'{!! route(\'backend.index\') !!}\',\n                dataType: \'json\',\n                delay: 250,\n                data: function (params) {\n                    return {\n                        q: params.q,\n                        term: params.term,\n                        sku_id: {{ request()-&gt;segment(3) }} // additional parameter\n                    };\n                },\n                processResults: function(data) {\n                    return {\n                        results: data.data,\n                        pagination: {\n                            more: data.next_page_url !== null\n                        }\n                    };\n                },\n                cache: true\n            },\n            // minimumInputLength: 1,\n            placeholder: \'İstifadəçi axtarın...\',\n            escapeMarkup: function(markup) {\n                return markup;\n            },\n            templateResult: function(data) {\n                return data.name;\n            },\n            templateSelection: function(data) {\n                return data.name;\n            },\n\n        });\n    });\n&lt;/script&gt;\n\n&lt;/body&gt;\n&lt;/html&gt;\n</code></pre>\n\n<p style=\"text-align:center\"><img src=\"https://blog.az-coders.com/files/photos/1/select2.png\" style=\"width:200px\" /></p>', '<p>&nbsp;&nbsp;</p>\n\n<pre>\n<code>web.php faylı</code></pre>\n\n<pre>\n<code class=\"language-php\">Route::get(\'/backend\', [BackendController::class,\'index\'])-&gt;name(\'backend.index\');</code></pre>\n\n<pre>\n<code>BackendController.php faylı</code></pre>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Http\\Controllers;\n\nuse App\\Models\\User;\n\nclass BackendController extends Controller\n{\n    public function index()\n    {\n        $search = \\request(\'term\');\n\n        $query = User::query();\n        if ($search) {\n            $query-&gt;where(\'name\', \'like\', \'%\' . $search . \'%\');\n        }\n\n        $users = $query-&gt;paginate(30);\n\n        return response()-&gt;json($users);\n    }\n}\n</code></pre>\n\n<pre>\n<code>users.blade.php faylı</code></pre>\n\n<pre>\n<code class=\"language-php\">&lt;!DOCTYPE html&gt;\n&lt;html lang=\"en\"&gt;\n&lt;head&gt;\n    &lt;meta charset=\"UTF-8\"&gt;\n    &lt;meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"&gt;\n    &lt;title&gt;Select2 with Laravel and AJAX&lt;/title&gt;\n    &lt;link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/select2/4.0.13/css/select2.min.css\" integrity=\"sha512-nMNlpuaDPrqlEls3IX/Q56H36qvBASwb3ipuo3MxeWbsQB1881ox0cRv7UPTgBlriqoynt35KjEwgGUeUXIPnw==\" crossorigin=\"anonymous\" referrerpolicy=\"no-referrer\" /&gt;\n&lt;/head&gt;\n&lt;body&gt;\n\n&lt;select id=\"mySelect\" style=\"width: 300px;\"&gt;\n    &lt;option value=\"\"&gt;İstifadəçi axtarın...&lt;/option&gt;\n&lt;/select&gt;\n\n&lt;script src=\"https://cdnjs.cloudflare.com/ajax/libs/jquery/3.7.1/jquery.min.js\" integrity=\"sha512-v2CJ7UaYy4JwqLDIrZUI/4hqeoQieOmAZNXBeQyjo21dadnwR+8ZaIJVT8EE2iyI61OV8e6M8PP2/4hpQINQ/g==\" crossorigin=\"anonymous\" referrerpolicy=\"no-referrer\"&gt;&lt;/script&gt;\n&lt;script src=\"https://cdnjs.cloudflare.com/ajax/libs/select2/4.0.13/js/select2.min.js\" integrity=\"sha512-2ImtlRlf2VVmiGZsjm9bEyhjGW4dU7B6TNwh/hx/iSByxNENtj3WVE6o/9Lj4TJeVXPi4bnOIMXFIJJAeufa0A==\" crossorigin=\"anonymous\" referrerpolicy=\"no-referrer\"&gt;&lt;/script&gt;\n&lt;script src=\"https://cdnjs.cloudflare.com/ajax/libs/select2/4.0.13/js/i18n/az.min.js\" integrity=\"sha512-5h/4MstAOhpL8LHF6e7tTEv31xdr5wY7JL9w7nqOI2zs/tL1ofuRfX+g+RwJ7l/3xc5cIAeLMLne6m+QYX67hg==\" crossorigin=\"anonymous\" referrerpolicy=\"no-referrer\"&gt;&lt;/script&gt;\n&lt;script&gt;\n    $(document).ready(function() {\n        $(\'#mySelect\').select2({\n            language: \"az\",\n            ajax: {\n                url: \'{!! route(\'backend.index\') !!}\',\n                dataType: \'json\',\n                delay: 250,\n                data: function (params) {\n                    return {\n                        q: params.q,\n                        term: params.term,\n                        sku_id: {{ request()-&gt;segment(3) }} // additional parameter\n                    };\n                },\n                processResults: function(data) {\n                    return {\n                        results: data.data,\n                        pagination: {\n                            more: data.next_page_url !== null\n                        }\n                    };\n                },\n                cache: true\n            },\n            // minimumInputLength: 1,\n            placeholder: \'İstifadəçi axtarın...\',\n            escapeMarkup: function(markup) {\n                return markup;\n            },\n            templateResult: function(data) {\n                return data.name;\n            },\n            templateSelection: function(data) {\n                return data.name;\n            },\n\n        });\n    });\n&lt;/script&gt;\n\n&lt;/body&gt;\n&lt;/html&gt;\n</code></pre>\n\n<p style=\"text-align:center\"><img src=\"https://blog.az-coders.com/files/photos/1/select2.png\" style=\"width:200px\" /></p>', 5, 0, '2024-02-26 17:46:58', '2024-02-28 21:59:40'),
(177, 'Laravel dinamik parametrləri ajaxda necə ötürə bilərəm?', 'Laravel dinamik parametrləri ajaxda necə ötürə bilərəm?', 'laravel-dinamik-parametrleri-ajaxda-nece-oture-bilerem', 'laravel-dinamik-parametrleri-ajaxda-nece-oture-bilerem', '<pre>\n<code class=\"language-php\">$(\'#reference_sku_id\').on(\'change\', function() {\n    let sku_id = $(this).val();\n    let url = \'{!! route(\'stocks.show\', \':id\') !!}\'.replace(\':id\', sku_id);\n\n    $.ajax({\n        url : url,\n        method : \'GET\',\n        success : function(response) {\n            console.log(response);\n        }\n    });\n});</code></pre>\n\n<p>&nbsp;</p>', '<pre>\n<code class=\"language-php\">$(\'#reference_sku_id\').on(\'change\', function() {\n    let sku_id = $(this).val();\n    let url = \'{!! route(\'stocks.show\', \':id\') !!}\'.replace(\':id\', sku_id);\n\n    $.ajax({\n        url : url,\n        method : \'GET\',\n        success : function(response) {\n            console.log(response);\n        }\n    });\n});</code></pre>', 5, 0, '2024-03-06 16:53:11', '2024-03-06 16:59:23'),
(178, 'resource and collection', 'resource and collection', 'resource-and-collection', 'resource-and-collection', '<pre>\n<code>HomeAboutChronologyResource.php</code></pre>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Http\\Resources\\Home;\n\nuse Illuminate\\Http\\Request;\nuse Illuminate\\Http\\Resources\\Json\\JsonResource;\n\nclass HomeAboutChronologyResource extends JsonResource\n{\n    /**\n     * Transform the resource into an array.\n     *\n     * @return array&lt;string, mixed&gt;\n     */\n    public function toArray(Request $request): array\n    {\n        return [\n            \'id\' =&gt; $this-&gt;id,\n            \'date\'=&gt;$this-&gt;date,\n            \'content\'=&gt;$this-&gt;content,\n        ];\n    }\n}\n</code></pre>\n\n<pre>\n<code>HomeAboutChronologyCollection.php</code></pre>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Http\\Resources\\Home;\n\nuse Illuminate\\Http\\Request;\nuse Illuminate\\Http\\Resources\\Json\\ResourceCollection;\n\nclass HomeAboutChronologyCollection extends ResourceCollection\n{\n    /**\n     * Transform the resource collection into an array.\n     *\n     * @return array&lt;int|string, mixed&gt;\n     */\n    public function toArray(Request $request): array\n    {\n        return [\n            $this-&gt;collection-&gt;transform(function ($chronlogy){\n                return new HomeAboutChronologyResource($chronlogy);\n            })\n        ];\n    }\n}\n</code></pre>\n\n<p>&nbsp;</p>', '<p>&nbsp;&nbsp;</p>\n\n<pre>\n<code>HomeAboutChronologyResource.php</code></pre>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Http\\Resources\\Home;\n\nuse Illuminate\\Http\\Request;\nuse Illuminate\\Http\\Resources\\Json\\JsonResource;\n\nclass HomeAboutChronologyResource extends JsonResource\n{\n    /**\n     * Transform the resource into an array.\n     *\n     * @return array&lt;string, mixed&gt;\n     */\n    public function toArray(Request $request): array\n    {\n        return [\n            \'id\' =&gt; $this-&gt;id,\n            \'date\'=&gt;$this-&gt;date,\n            \'content\'=&gt;$this-&gt;content,\n        ];\n    }\n}\n</code></pre>\n\n<pre>\n<code>HomeAboutChronologyCollection.php</code></pre>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Http\\Resources\\Home;\n\nuse Illuminate\\Http\\Request;\nuse Illuminate\\Http\\Resources\\Json\\ResourceCollection;\n\nclass HomeAboutChronologyCollection extends ResourceCollection\n{\n    /**\n     * Transform the resource collection into an array.\n     *\n     * @return array&lt;int|string, mixed&gt;\n     */\n    public function toArray(Request $request): array\n    {\n        return [\n            $this-&gt;collection-&gt;transform(function ($chronlogy){\n                return new HomeAboutChronologyResource($chronlogy);\n            })\n        ];\n    }\n}\n</code></pre>\n\n<p>&nbsp;</p>', 5, 0, '2024-03-11 14:55:01', '2024-03-11 14:55:01');
INSERT INTO `blogs` (`id`, `titleEn`, `titleAz`, `slugEn`, `slugAz`, `blogEn`, `blogAz`, `category_id`, `view`, `created_at`, `updated_at`) VALUES
(179, 'select2 live search with server side', 'select2 live search with server side', 'select2-live-search-with-server-side', 'select2-live-search-with-server-side', '<p>&nbsp;&nbsp;1. in web.php file</p>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nuse App\\Http\\Controllers\\BackendController;\nuse Illuminate\\Support\\Facades\\Route;\n\nRoute::get(\'/\', function () {\n    return view(\'welcome\');\n});\n\nRoute::get(\'/backend\', [BackendController::class,\'index\'])-&gt;name(\'backend.index\');</code></pre>\n\n<p>2. in BackendController.php file</p>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Http\\Controllers;\n\nuse App\\Models\\User;\n\nclass BackendController extends Controller\n{\n    public function index()\n    {\n        $search = \\request(\'term\');\n\n        $query = User::query();\n        if ($search) {\n            $query-&gt;where(\'name\', \'like\', \'%\' . $search . \'%\');\n        }\n\n        $users = $query-&gt;paginate(10);\n\n        return response()-&gt;json($users);\n    }\n}\n</code></pre>\n\n<p>3. in welcome.blade.php file</p>\n\n<pre>\n<code class=\"language-php\">&lt;!DOCTYPE html&gt;\n&lt;html lang=\"en\"&gt;\n\n&lt;head&gt;\n    &lt;meta charset=\"UTF-8\"&gt;\n    &lt;meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"&gt;\n    &lt;title&gt;Select2 with Laravel and AJAX&lt;/title&gt;\n    &lt;link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/select2/4.0.13/css/select2.min.css\"\n        integrity=\"sha512-nMNlpuaDPrqlEls3IX/Q56H36qvBASwb3ipuo3MxeWbsQB1881ox0cRv7UPTgBlriqoynt35KjEwgGUeUXIPnw==\"\n        crossorigin=\"anonymous\" referrerpolicy=\"no-referrer\" /&gt;\n\n    &lt;style&gt;\n\n        span.select2-selection__arrow {\n            display: none;\n        }\n\n        .envelope {\n            background-color: #fff;\n            height: 240px;\n            width: 300px;\n            z-index: 99999 !important;\n            position: absolute;\n            top: 40px;\n            border-top: 1px solid #5897fb;\n        }\n\n        .my-d-none{\n            display: none;\n        }\n\n    &lt;/style&gt;\n&lt;/head&gt;\n\n&lt;body&gt;\n\n    &lt;form action=\"\" method=\"GET\" onsubmit=\"return false\"&gt;\n        &lt;div id=\"select-container\"&gt;\n            &lt;div class=\"envelope\"&gt;&lt;/div&gt;\n            &lt;select id=\"mySelect\" name=\"mySelect\" style=\"width: 300px;\"&gt;\n                &lt;option value=\"\"&gt;İstifadəçi axtarın...&lt;/option&gt;\n            &lt;/select&gt;\n        &lt;/div&gt;\n\n    &lt;/form&gt;\n\n    &lt;script src=\"https://cdnjs.cloudflare.com/ajax/libs/jquery/3.7.1/jquery.min.js\"\n        integrity=\"sha512-v2CJ7UaYy4JwqLDIrZUI/4hqeoQieOmAZNXBeQyjo21dadnwR+8ZaIJVT8EE2iyI61OV8e6M8PP2/4hpQINQ/g==\"\n        crossorigin=\"anonymous\" referrerpolicy=\"no-referrer\"&gt;&lt;/script&gt;\n    &lt;script src=\"https://cdnjs.cloudflare.com/ajax/libs/select2/4.0.13/js/select2.min.js\"\n        integrity=\"sha512-2ImtlRlf2VVmiGZsjm9bEyhjGW4dU7B6TNwh/hx/iSByxNENtj3WVE6o/9Lj4TJeVXPi4bnOIMXFIJJAeufa0A==\"\n        crossorigin=\"anonymous\" referrerpolicy=\"no-referrer\"&gt;&lt;/script&gt;\n    &lt;script src=\"https://cdnjs.cloudflare.com/ajax/libs/select2/4.0.13/js/i18n/az.min.js\"\n        integrity=\"sha512-5h/4MstAOhpL8LHF6e7tTEv31xdr5wY7JL9w7nqOI2zs/tL1ofuRfX+g+RwJ7l/3xc5cIAeLMLne6m+QYX67hg==\"\n        crossorigin=\"anonymous\" referrerpolicy=\"no-referrer\"&gt;&lt;/script&gt;\n    &lt;script&gt;\n        $(document).ready(function() {\n\n\n            $(\'#mySelect\').select2({\n                language: \"az\",\n                ajax: {\n                    url: \'{!! route(\'backend.index\') !!}\',\n                    dataType: \'json\',\n                    delay: 250,\n                    headers: {\n                        \'X-CSRF-Token\': $(\'meta[name=\"_token\"]\').attr(\'content\'),\n                    },\n                    processResults: function(data) {\n                        return {\n                            results: data.data,\n                            pagination: {\n                                more: data.next_page_url !== null\n                            }\n                        };\n                    },\n                    cache: true\n                },\n                minimumInputLength: 0,\n                placeholder: \'İstifadəçi axtarın...\',\n                escapeMarkup: function(markup) {\n                    return markup;\n                },\n                templateResult: function(data) {\n                    return data.name;\n                },\n                templateSelection: function(data) {\n                    return data.name ?? \'İstifadəçi axtarın...\';\n                },\n                theme: \"classic\",\n            }).on(\"select2:closing\", function(e) {\n                e.preventDefault();\n            }).select2(\'open\');\n        });\n\n        $(document).on(\'click\', \'span.select2.select2-container.select2-container--classic.select2-container--below.select2-container--open\', function () {\n            let checkOpening = $(\'.envelope\').attr(\'class\');\n\n            if(checkOpening == \'envelope\')\n            {\n                $(\'.envelope\').addClass(\'my-d-none\');\n            }\n            else\n            {\n                $(\'.envelope\').removeClass(\'my-d-none\');\n            }\n        });\n    &lt;/script&gt;\n\n&lt;/body&gt;\n\n&lt;/html&gt;\n</code></pre>\n\n<p>&nbsp;</p>', '<p>&nbsp;&nbsp;1. in web.php file</p>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nuse App\\Http\\Controllers\\BackendController;\nuse Illuminate\\Support\\Facades\\Route;\n\nRoute::get(\'/\', function () {\n    return view(\'welcome\');\n});\n\nRoute::get(\'/backend\', [BackendController::class,\'index\'])-&gt;name(\'backend.index\');</code></pre>\n\n<p>2. in BackendController.php file</p>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Http\\Controllers;\n\nuse App\\Models\\User;\n\nclass BackendController extends Controller\n{\n    public function index()\n    {\n        $search = \\request(\'term\');\n\n        $query = User::query();\n        if ($search) {\n            $query-&gt;where(\'name\', \'like\', \'%\' . $search . \'%\');\n        }\n\n        $users = $query-&gt;paginate(10);\n\n        return response()-&gt;json($users);\n    }\n}\n</code></pre>\n\n<p>3. in welcome.blade.php file</p>\n\n<pre>\n<code class=\"language-php\">&lt;!DOCTYPE html&gt;\n&lt;html lang=\"en\"&gt;\n\n&lt;head&gt;\n    &lt;meta charset=\"UTF-8\"&gt;\n    &lt;meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"&gt;\n    &lt;title&gt;Select2 with Laravel and AJAX&lt;/title&gt;\n    &lt;link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/select2/4.0.13/css/select2.min.css\"\n        integrity=\"sha512-nMNlpuaDPrqlEls3IX/Q56H36qvBASwb3ipuo3MxeWbsQB1881ox0cRv7UPTgBlriqoynt35KjEwgGUeUXIPnw==\"\n        crossorigin=\"anonymous\" referrerpolicy=\"no-referrer\" /&gt;\n\n    &lt;style&gt;\n\n        span.select2-selection__arrow {\n            display: none;\n        }\n\n        .envelope {\n            background-color: #fff;\n            height: 240px;\n            width: 300px;\n            z-index: 99999 !important;\n            position: absolute;\n            top: 40px;\n            border-top: 1px solid #5897fb;\n        }\n\n        .my-d-none{\n            display: none;\n        }\n\n    &lt;/style&gt;\n&lt;/head&gt;\n\n&lt;body&gt;\n\n    &lt;form action=\"\" method=\"GET\" onsubmit=\"return false\"&gt;\n        &lt;div id=\"select-container\"&gt;\n            &lt;div class=\"envelope\"&gt;&lt;/div&gt;\n            &lt;select id=\"mySelect\" name=\"mySelect\" style=\"width: 300px;\"&gt;\n                &lt;option value=\"\"&gt;İstifadəçi axtarın...&lt;/option&gt;\n            &lt;/select&gt;\n        &lt;/div&gt;\n\n    &lt;/form&gt;\n\n    &lt;script src=\"https://cdnjs.cloudflare.com/ajax/libs/jquery/3.7.1/jquery.min.js\"\n        integrity=\"sha512-v2CJ7UaYy4JwqLDIrZUI/4hqeoQieOmAZNXBeQyjo21dadnwR+8ZaIJVT8EE2iyI61OV8e6M8PP2/4hpQINQ/g==\"\n        crossorigin=\"anonymous\" referrerpolicy=\"no-referrer\"&gt;&lt;/script&gt;\n    &lt;script src=\"https://cdnjs.cloudflare.com/ajax/libs/select2/4.0.13/js/select2.min.js\"\n        integrity=\"sha512-2ImtlRlf2VVmiGZsjm9bEyhjGW4dU7B6TNwh/hx/iSByxNENtj3WVE6o/9Lj4TJeVXPi4bnOIMXFIJJAeufa0A==\"\n        crossorigin=\"anonymous\" referrerpolicy=\"no-referrer\"&gt;&lt;/script&gt;\n    &lt;script src=\"https://cdnjs.cloudflare.com/ajax/libs/select2/4.0.13/js/i18n/az.min.js\"\n        integrity=\"sha512-5h/4MstAOhpL8LHF6e7tTEv31xdr5wY7JL9w7nqOI2zs/tL1ofuRfX+g+RwJ7l/3xc5cIAeLMLne6m+QYX67hg==\"\n        crossorigin=\"anonymous\" referrerpolicy=\"no-referrer\"&gt;&lt;/script&gt;\n    &lt;script&gt;\n        $(document).ready(function() {\n\n\n            $(\'#mySelect\').select2({\n                language: \"az\",\n                ajax: {\n                    url: \'{!! route(\'backend.index\') !!}\',\n                    dataType: \'json\',\n                    delay: 250,\n                    headers: {\n                        \'X-CSRF-Token\': $(\'meta[name=\"_token\"]\').attr(\'content\'),\n                    },\n                    processResults: function(data) {\n                        return {\n                            results: data.data,\n                            pagination: {\n                                more: data.next_page_url !== null\n                            }\n                        };\n                    },\n                    cache: true\n                },\n                minimumInputLength: 0,\n                placeholder: \'İstifadəçi axtarın...\',\n                escapeMarkup: function(markup) {\n                    return markup;\n                },\n                templateResult: function(data) {\n                    return data.name;\n                },\n                templateSelection: function(data) {\n                    return data.name ?? \'İstifadəçi axtarın...\';\n                },\n                theme: \"classic\",\n            }).on(\"select2:closing\", function(e) {\n                e.preventDefault();\n            }).select2(\'open\');\n        });\n\n        $(document).on(\'click\', \'span.select2.select2-container.select2-container--classic.select2-container--below.select2-container--open\', function () {\n            let checkOpening = $(\'.envelope\').attr(\'class\');\n\n            if(checkOpening == \'envelope\')\n            {\n                $(\'.envelope\').addClass(\'my-d-none\');\n            }\n            else\n            {\n                $(\'.envelope\').removeClass(\'my-d-none\');\n            }\n        });\n    &lt;/script&gt;\n\n&lt;/body&gt;\n\n&lt;/html&gt;\n</code></pre>\n\n<p>&nbsp;</p>', 5, 0, '2024-03-29 14:42:57', '2024-03-29 14:44:59'),
(180, 'Bir method yazın int array qəbul etsin.Bu method boolean dəyər geri qaytarsın.Method yoxlasın ki,bu array sorted-dir yoxsa yox', 'Bir method yazın int array qəbul etsin.Bu method boolean dəyər geri qaytarsın.Method yoxlasın ki,bu array sorted-dir yoxsa yox', 'bir-method-yazin-int-array-qebul-etsinbu-method-boolean-deyer-geri-qaytarsinmethod-yoxlasin-kibu-array-sorted-dir-yoxsa-yox', 'bir-method-yazin-int-array-qebul-etsinbu-method-boolean-deyer-geri-qaytarsinmethod-yoxlasin-kibu-array-sorted-dir-yoxsa-yox', '<pre>\n<code class=\"language-java\">public class Main {\n    public static void main(String[] args) {\n        int[] array1 = {1, 2, 3, 4, 5};\n        int[] array2 = {5, 4, 3, 2, 1};\n        System.out.println(\"array1 \" + (isSorted(array1) ? \" sıralıdır\" : \" sıralı deyil\"));\n        System.out.println(\"array2 \" + (isSorted(array2) ? \" sıralıdır\" : \" sıralı deyil\"));\n    }\n\n    public static boolean isSorted(int[] array) {\n        if (array.length &lt;= 1) {\n            return true;\n        }\n\n        for (int i = 0; i &lt; array.length - 1; i++) {\n            if (array[i] &gt; array[i + 1]) {\n                return false;\n            }\n        }\n        return true;\n    }\n}</code></pre>\n\n<p>&nbsp;</p>', '<pre>\n<code class=\"language-java\">public class Main {\n    public static void main(String[] args) {\n        int[] array1 = {1, 2, 3, 4, 5};\n        int[] array2 = {5, 4, 3, 2, 1};\n        System.out.println(\"array1 \" + (isSorted(array1) ? \" sıralıdır\" : \" sıralı deyil\"));\n        System.out.println(\"array2 \" + (isSorted(array2) ? \" sıralıdır\" : \" sıralı deyil\"));\n    }\n\n    public static boolean isSorted(int[] array) {\n        if (array.length &lt;= 1) {\n            return true;\n        }\n\n        for (int i = 0; i &lt; array.length - 1; i++) {\n            if (array[i] &gt; array[i + 1]) {\n                return false;\n            }\n        }\n        return true;\n    }\n}</code></pre>', 22, 0, '2024-05-03 18:40:08', '2024-05-03 18:41:25'),
(181, 'Bir method yazın int array qəbul etsin.Bu arrayin daxilində olan elementlərin cəmini tapib geri qaytarsin.', 'Bir method yazın int array qəbul etsin.Bu arrayin daxilində olan elementlərin cəmini tapib geri qaytarsin.', 'bir-method-yazin-int-array-qebul-etsinbu-arrayin-daxilinde-olan-elementlerin-cemini-tapib-geri-qaytarsin', 'bir-method-yazin-int-array-qebul-etsinbu-arrayin-daxilinde-olan-elementlerin-cemini-tapib-geri-qaytarsin', '<pre>\n<code class=\"language-java\">public class Main {\n    public static void main(String[] args) {\n        int[] array = {1, 2, 3, 4, 5};\n\n        System.out.println(\"cem = \" + sumArray(array));\n    }\n\n    public static int sumArray(int[] array) {\n        int cem = 0;\n        for (int i = 0; i &lt;= array.length - 1; i++) {\n            cem += array[i];\n        }\n\n        return cem;\n    }\n}</code></pre>\n\n<p>&nbsp;</p>', '<pre>\n<code class=\"language-java\">public class Main {\n    public static void main(String[] args) {\n        int[] array = {1, 2, 3, 4, 5};\n\n        System.out.println(\"cem = \" + sumArray(array));\n    }\n\n    public static int sumArray(int[] array) {\n        int cem = 0;\n        for (int i = 0; i &lt;= array.length - 1; i++) {\n            cem += array[i];\n        }\n\n        return cem;\n    }\n}</code></pre>\n\n<p>&nbsp;</p>', 22, 0, '2024-05-03 18:48:42', '2024-05-03 18:48:42'),
(182, 'FIFO metodu ilə satılmış məhsulların maya dəyərini hesablamaq', 'FIFO metodu ilə satılmış məhsulların maya dəyərini hesablamaq', 'fifo-metodu-ile-satilmis-mehsullarin-maya-deyerini-hesablamaq', 'fifo-metodu-ile-satilmis-mehsullarin-maya-deyerini-hesablamaq', '<pre>\n<code class=\"language-sql\">DELIMITER $$\nCREATE DEFINER=`u623198832_pos`@`127.0.0.1` FUNCTION `calculateSalesItemCost`(stock_id INT, input_date DATE) RETURNS decimal(16,2)\n    READS SQL DATA\nBEGIN\n    DECLARE sold BIGINT DEFAULT 0;\n    DECLARE inpItemCount INT;\n    DECLARE inpItemCost DECIMAL(16,2);\n    DECLARE cost DECIMAL(16,2) DEFAULT 0;\n    DECLARE done INT DEFAULT 0;\n\n    DECLARE cur_purchase CURSOR FOR\n        SELECT SUM(itp.count) AS Say, itp.maya_deyeri\n        FROM input_products itp\n        JOIN invoices inv ON inv.id = itp.invoice_id\n        WHERE itp.stock_id = stock_id\n        GROUP BY itp.maya_deyeri, inv.date\n        ORDER BY inv.date ASC;\n\n    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;\n\n    IF input_date IS NULL THEN\n        SET input_date = CURDATE();\n    END IF;\n\n    -- Calculate sold items count\n    SET sold = (SELECT IFNULL(SUM(sl.count), 0) FROM sales sl WHERE sl.finished = 1 AND sl.stock_id = stock_id AND DATE(sl.updated_at) &lt;= DATE(input_date));\n\n    OPEN cur_purchase;\n\n    read_loop: LOOP\n        FETCH cur_purchase INTO inpItemCount, inpItemCost;\n        IF done THEN\n            LEAVE read_loop;\n        END IF;\n\n        IF sold &lt;= inpItemCount THEN\n            SET cost = cost + (sold * inpItemCost);\n            SET sold = 0;\n        ELSE\n            SET cost = cost + (inpItemCount * inpItemCost);\n            SET sold = sold - inpItemCount;\n        END IF;\n    END LOOP;\n\n    CLOSE cur_purchase;\n\n    RETURN cost;\nEND$$\nDELIMITER ;</code></pre>\n\n<pre>\n<code class=\"language-php\">$startYMD = Carbon::parse($start)-&gt;format(\'Y-m-d\');\n$endYMD = Carbon::parse($end)-&gt;format(\'Y-m-d\');\n\n$t1_saled_cost = DB::table(DB::raw(\'(SELECT\nsl.stock_id,\nSUM(sl.count) AS say,\ncalculateSalesItemCost(sl.stock_id, \"\'.$startYMD.\'\") AS MayaDeyeri\nFROM sales sl\nGROUP BY sl.stock_id\n) as sub\'))\n    -&gt;select(DB::raw(\'SUM(MayaDeyeri) as total_cost\'))\n    -&gt;first();\n\n$t2_saled_cost = DB::table(DB::raw(\'(SELECT\nsl.stock_id,\nSUM(sl.count) AS say,\ncalculateSalesItemCost(sl.stock_id, \"\'.$endYMD.\'\") AS MayaDeyeri\nFROM sales sl\nGROUP BY sl.stock_id\n) as sub\'))\n    -&gt;select(DB::raw(\'SUM(MayaDeyeri) as total_cost\'))\n    -&gt;first();</code></pre>\n\n<p>&nbsp;</p>', '<p>&nbsp;&nbsp;</p>\n\n<pre>\n<code class=\"language-sql\">DELIMITER $$\nCREATE DEFINER=`u623198832_pos`@`127.0.0.1` FUNCTION `calculateSalesItemCost`(stock_id INT, input_date DATE) RETURNS decimal(16,2)\n    READS SQL DATA\nBEGIN\n    DECLARE sold BIGINT DEFAULT 0;\n    DECLARE inpItemCount INT;\n    DECLARE inpItemCost DECIMAL(16,2);\n    DECLARE cost DECIMAL(16,2) DEFAULT 0;\n    DECLARE done INT DEFAULT 0;\n\n    DECLARE cur_purchase CURSOR FOR\n        SELECT SUM(itp.count) AS Say, itp.maya_deyeri\n        FROM input_products itp\n        JOIN invoices inv ON inv.id = itp.invoice_id\n        WHERE itp.stock_id = stock_id\n        GROUP BY itp.maya_deyeri, inv.date\n        ORDER BY inv.date ASC;\n\n    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;\n\n    IF input_date IS NULL THEN\n        SET input_date = CURDATE();\n    END IF;\n\n    -- Calculate sold items count\n    SET sold = (SELECT IFNULL(SUM(sl.count), 0) FROM sales sl WHERE sl.finished = 1 AND sl.stock_id = stock_id AND DATE(sl.updated_at) &lt;= DATE(input_date));\n\n    OPEN cur_purchase;\n\n    read_loop: LOOP\n        FETCH cur_purchase INTO inpItemCount, inpItemCost;\n        IF done THEN\n            LEAVE read_loop;\n        END IF;\n\n        IF sold &lt;= inpItemCount THEN\n            SET cost = cost + (sold * inpItemCost);\n            SET sold = 0;\n        ELSE\n            SET cost = cost + (inpItemCount * inpItemCost);\n            SET sold = sold - inpItemCount;\n        END IF;\n    END LOOP;\n\n    CLOSE cur_purchase;\n\n    RETURN cost;\nEND$$\nDELIMITER ;</code></pre>\n\n<pre>\n<code class=\"language-php\">$startYMD = Carbon::parse($start)-&gt;format(\'Y-m-d\');\n$endYMD = Carbon::parse($end)-&gt;format(\'Y-m-d\');\n\n$t1_saled_cost = DB::table(DB::raw(\'(SELECT\nsl.stock_id,\nSUM(sl.count) AS say,\ncalculateSalesItemCost(sl.stock_id, \"\'.$startYMD.\'\") AS MayaDeyeri\nFROM sales sl\nGROUP BY sl.stock_id\n) as sub\'))\n    -&gt;select(DB::raw(\'SUM(MayaDeyeri) as total_cost\'))\n    -&gt;first();\n\n$t2_saled_cost = DB::table(DB::raw(\'(SELECT\nsl.stock_id,\nSUM(sl.count) AS say,\ncalculateSalesItemCost(sl.stock_id, \"\'.$endYMD.\'\") AS MayaDeyeri\nFROM sales sl\nGROUP BY sl.stock_id\n) as sub\'))\n    -&gt;select(DB::raw(\'SUM(MayaDeyeri) as total_cost\'))\n    -&gt;first();</code></pre>\n\n<p>&nbsp;</p>', 5, 0, '2024-06-03 08:46:30', '2024-06-03 08:46:30'),
(183, 'Laraveldə necə mail göndərə bilərəm?', 'Laraveldə necə mail göndərə bilərəm?', 'laravelde-nece-mail-gondere-bilerem', 'laravelde-nece-mail-gondere-bilerem', '<p>1) app/Mail/ContactEmail.php faylı</p>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Mail;\n\nuse Illuminate\\Bus\\Queueable;\nuse Illuminate\\Contracts\\Queue\\ShouldQueue;\nuse Illuminate\\Mail\\Mailable;\nuse Illuminate\\Queue\\SerializesModels;\n\nclass ContactEmail extends Mailable\n{\n    use Queueable, SerializesModels;\n    public $details;\n    /**\n     * Create a new message instance.\n     *\n     * @return void\n     */\n    public function __construct($details)\n    {\n        $this-&gt;details = $details;\n    }\n\n    /**\n     * Build the message.\n     *\n     * @return $this\n     */\n    public function build(): static\n    {\n        return $this-&gt;subject(\'Yeni elektron müraciət daxil oldu.\')\n            -&gt;replyTo(\'no-reply@gmail.com\', \'No reply\')\n            -&gt;markdown(\'emails.contact-mail\');\n    }\n}\n</code></pre>\n\n<p>2)resources/views/emails/contact-mail.blade.php</p>\n\n<pre>\n<code class=\"language-php\">&lt;p&gt;Ad : {!! $details[\'name\'] !!}&lt;/p&gt;\n&lt;p&gt;Soyad : {!! $details[\'surname\'] !!}&lt;/p&gt;\n&lt;p&gt;Tel : {!! $details[\'phone\'] !!}&lt;/p&gt;\n&lt;p&gt;Fayl : &lt;a href=\"{!! $details[\'file\'] !!}\"&gt;Faylı endir&lt;/a&gt;&lt;/p&gt;\n\n{{ config(\'app.name\') }} © {{ date(\'Y\') }}</code></pre>\n\n<p>3) config/mail.php</p>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nreturn [\n    \'default\' =&gt; env(\'MAIL_MAILER\', \'smtp\'),\n    \'mailers\' =&gt; [\n        \'smtp\' =&gt; [\n            \'transport\' =&gt; \'smtp\',\n            \'host\' =&gt; env(\'MAIL_HOST\', \'smtp.mailgun.org\'),\n            \'port\' =&gt; env(\'MAIL_PORT\', 587),\n            \'encryption\' =&gt; env(\'MAIL_ENCRYPTION\', \'tls\'),\n            \'username\' =&gt; env(\'MAIL_USERNAME\'),\n            \'password\' =&gt; env(\'MAIL_PASSWORD\'),\n            \'timeout\' =&gt; null,\n            \'local_domain\' =&gt; env(\'MAIL_EHLO_DOMAIN\'),\n        ],\n        \'ses\' =&gt; [\n            \'transport\' =&gt; \'ses\',\n        ],\n        \'mailgun\' =&gt; [\n            \'transport\' =&gt; \'mailgun\',\n        ],\n        \'postmark\' =&gt; [\n            \'transport\' =&gt; \'postmark\',\n        ],\n        \'sendmail\' =&gt; [\n            \'transport\' =&gt; \'sendmail\',\n            \'path\' =&gt; env(\'MAIL_SENDMAIL_PATH\', \'/usr/sbin/sendmail -bs -i\'),\n        ],\n        \'log\' =&gt; [\n            \'transport\' =&gt; \'log\',\n            \'channel\' =&gt; env(\'MAIL_LOG_CHANNEL\'),\n        ],\n        \'array\' =&gt; [\n            \'transport\' =&gt; \'array\',\n        ],\n        \'failover\' =&gt; [\n            \'transport\' =&gt; \'failover\',\n            \'mailers\' =&gt; [\n                \'smtp\',\n                \'log\',\n            ],\n        ],\n    ],\n    \'from\' =&gt; [\n        \'address\' =&gt; env(\'MAIL_FROM_ADDRESS\', \'hello@example.com\'),\n        \'name\' =&gt; env(\'MAIL_FROM_NAME\', \'Example\'),\n    ],\n    \'markdown\' =&gt; [\n        \'theme\' =&gt; \'default\',\n\n        \'paths\' =&gt; [\n            resource_path(\'views/vendor/mail\'),\n        ],\n    ],\n];\n</code></pre>\n\n<p>4)&nbsp;QiymetlendirmeController.php&nbsp;</p>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Http\\Controllers\\Front;\n\nuse App\\Http\\Controllers\\Controller;\nuse App\\Mail\\ContactEmail;\nuse App\\Models\\Qiymetlendirme;\nuse App\\Models\\StaticPages;\nuse App\\Traits\\FileUploader;\nuse Illuminate\\Http\\Request;\nuse Illuminate\\Support\\Facades\\Mail;\n\nclass QiymetlendirmeController extends Controller\n{\n    use FileUploader;\n\n    public function qiymetlendirmeStore(Request $request)\n    {\n        $request-&gt;validate([\n            \'name\' =&gt; \'required|string|max:255\',\n            \'surname\' =&gt; \'required|string|max:255\',\n            \'phone\' =&gt; \'required|string|max:255\',\n            \'file\' =&gt; \'required|file|mimes:xls,xlsx|max:2048\',\n        ], [], [\n            \'name\' =&gt; __(\'static.ad\'),\n            \'surname\' =&gt; __(\'static.soyad\'),\n            \'phone\' =&gt; __(\'static.telefon\'),\n            \'file\' =&gt; \'Fayl\'\n        ]);\n\n        $file = $this-&gt;fileSave(\'files/qiymetlendirme/\', $request, \'file\');\n\n        $qiymetlendirme = Qiymetlendirme::create([\n            \'name\' =&gt; $request-&gt;name,\n            \'surname\' =&gt; $request-&gt;surname,\n            \'phone\' =&gt; $request-&gt;phone,\n            \'file\' =&gt; $file,\n        ]);\n\n        $details = [\n            \'name\' =&gt; $qiymetlendirme-&gt;name,\n            \'surname\' =&gt; $qiymetlendirme-&gt;surname,\n            \'phone\' =&gt; $qiymetlendirme-&gt;phone,\n            \'file\' =&gt; asset(\'files/qiymetlendirme/\' . $file),\n        ];\n\n        Mail::to(\'rahim.suleymanov94@gmail.com\')-&gt;send(new ContactEmail($details));\n\n        return response()-&gt;json([\'message\' =&gt; __(\'static.qiymetlendirme_message\')]);\n    }\n}\n</code></pre>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;</p>', '<p>&nbsp;1) app/Mail/ContactEmail.php faylı</p>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Mail;\n\nuse Illuminate\\Bus\\Queueable;\nuse Illuminate\\Contracts\\Queue\\ShouldQueue;\nuse Illuminate\\Mail\\Mailable;\nuse Illuminate\\Queue\\SerializesModels;\n\nclass ContactEmail extends Mailable\n{\n    use Queueable, SerializesModels;\n    public $details;\n    /**\n     * Create a new message instance.\n     *\n     * @return void\n     */\n    public function __construct($details)\n    {\n        $this-&gt;details = $details;\n    }\n\n    /**\n     * Build the message.\n     *\n     * @return $this\n     */\n    public function build(): static\n    {\n        return $this-&gt;subject(\'Yeni elektron müraciət daxil oldu.\')\n            -&gt;replyTo(\'no-reply@gmail.com\', \'No reply\')\n            -&gt;markdown(\'emails.contact-mail\');\n    }\n}\n</code></pre>\n\n<p>2)resources/views/emails/contact-mail.blade.php</p>\n\n<pre>\n<code class=\"language-php\">&lt;p&gt;Ad : {!! $details[\'name\'] !!}&lt;/p&gt;\n&lt;p&gt;Soyad : {!! $details[\'surname\'] !!}&lt;/p&gt;\n&lt;p&gt;Tel : {!! $details[\'phone\'] !!}&lt;/p&gt;\n&lt;p&gt;Fayl : &lt;a href=\"{!! $details[\'file\'] !!}\"&gt;Faylı endir&lt;/a&gt;&lt;/p&gt;\n\n{{ config(\'app.name\') }} © {{ date(\'Y\') }}</code></pre>\n\n<p>3) config/mail.php</p>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nreturn [\n    \'default\' =&gt; env(\'MAIL_MAILER\', \'smtp\'),\n    \'mailers\' =&gt; [\n        \'smtp\' =&gt; [\n            \'transport\' =&gt; \'smtp\',\n            \'host\' =&gt; env(\'MAIL_HOST\', \'smtp.mailgun.org\'),\n            \'port\' =&gt; env(\'MAIL_PORT\', 587),\n            \'encryption\' =&gt; env(\'MAIL_ENCRYPTION\', \'tls\'),\n            \'username\' =&gt; env(\'MAIL_USERNAME\'),\n            \'password\' =&gt; env(\'MAIL_PASSWORD\'),\n            \'timeout\' =&gt; null,\n            \'local_domain\' =&gt; env(\'MAIL_EHLO_DOMAIN\'),\n        ],\n        \'ses\' =&gt; [\n            \'transport\' =&gt; \'ses\',\n        ],\n        \'mailgun\' =&gt; [\n            \'transport\' =&gt; \'mailgun\',\n        ],\n        \'postmark\' =&gt; [\n            \'transport\' =&gt; \'postmark\',\n        ],\n        \'sendmail\' =&gt; [\n            \'transport\' =&gt; \'sendmail\',\n            \'path\' =&gt; env(\'MAIL_SENDMAIL_PATH\', \'/usr/sbin/sendmail -bs -i\'),\n        ],\n        \'log\' =&gt; [\n            \'transport\' =&gt; \'log\',\n            \'channel\' =&gt; env(\'MAIL_LOG_CHANNEL\'),\n        ],\n        \'array\' =&gt; [\n            \'transport\' =&gt; \'array\',\n        ],\n        \'failover\' =&gt; [\n            \'transport\' =&gt; \'failover\',\n            \'mailers\' =&gt; [\n                \'smtp\',\n                \'log\',\n            ],\n        ],\n    ],\n    \'from\' =&gt; [\n        \'address\' =&gt; env(\'MAIL_FROM_ADDRESS\', \'hello@example.com\'),\n        \'name\' =&gt; env(\'MAIL_FROM_NAME\', \'Example\'),\n    ],\n    \'markdown\' =&gt; [\n        \'theme\' =&gt; \'default\',\n\n        \'paths\' =&gt; [\n            resource_path(\'views/vendor/mail\'),\n        ],\n    ],\n];\n</code></pre>\n\n<p>4)&nbsp;QiymetlendirmeController.php&nbsp;</p>\n\n<pre>\n<code class=\"language-php\">&lt;?php\n\nnamespace App\\Http\\Controllers\\Front;\n\nuse App\\Http\\Controllers\\Controller;\nuse App\\Mail\\ContactEmail;\nuse App\\Models\\Qiymetlendirme;\nuse App\\Models\\StaticPages;\nuse App\\Traits\\FileUploader;\nuse Illuminate\\Http\\Request;\nuse Illuminate\\Support\\Facades\\Mail;\n\nclass QiymetlendirmeController extends Controller\n{\n    use FileUploader;\n\n    public function qiymetlendirmeStore(Request $request)\n    {\n        $request-&gt;validate([\n            \'name\' =&gt; \'required|string|max:255\',\n            \'surname\' =&gt; \'required|string|max:255\',\n            \'phone\' =&gt; \'required|string|max:255\',\n            \'file\' =&gt; \'required|file|mimes:xls,xlsx|max:2048\',\n        ], [], [\n            \'name\' =&gt; __(\'static.ad\'),\n            \'surname\' =&gt; __(\'static.soyad\'),\n            \'phone\' =&gt; __(\'static.telefon\'),\n            \'file\' =&gt; \'Fayl\'\n        ]);\n\n        $file = $this-&gt;fileSave(\'files/qiymetlendirme/\', $request, \'file\');\n\n        $qiymetlendirme = Qiymetlendirme::create([\n            \'name\' =&gt; $request-&gt;name,\n            \'surname\' =&gt; $request-&gt;surname,\n            \'phone\' =&gt; $request-&gt;phone,\n            \'file\' =&gt; $file,\n        ]);\n\n        $details = [\n            \'name\' =&gt; $qiymetlendirme-&gt;name,\n            \'surname\' =&gt; $qiymetlendirme-&gt;surname,\n            \'phone\' =&gt; $qiymetlendirme-&gt;phone,\n            \'file\' =&gt;