(202, 'bootstrap dropdown menu items right', 'bootstrap dropdown menu items right', 'bootstrap-dropdown-menu-items-right', 'bootstrap-dropdown-menu-items-right', '<pre>\n<code class=\"language-html\">&lt;div class=\"dropdown-menu dropdown-menu-end\"&gt;\n    &lt;a class=\"dropdown-item\" href=\"#\"&gt;Link&lt;/a&gt;\n    &lt;a class=\"dropdown-item\" href=\"#\"&gt;Link&lt;/a&gt;\n    &lt;a class=\"dropdown-item\" href=\"#\"&gt;Link&lt;/a&gt;\n&lt;/div&gt;</code></pre>\n\n<p>&nbsp;</p>', '<pre>\n<code class=\"language-html\">&lt;div class=\"dropdown-menu dropdown-menu-end\"&gt;\n    &lt;a class=\"dropdown-item\" href=\"#\"&gt;Link&lt;/a&gt;\n    &lt;a class=\"dropdown-item\" href=\"#\"&gt;Link&lt;/a&gt;\n    &lt;a class=\"dropdown-item\" href=\"#\"&gt;Link&lt;/a&gt;\n&lt;/div&gt;</code></pre>', 7, 0, '2024-11-25 09:35:12', '2024-11-25 09:35:12'),
(203, 'git clone remote server private project', 'git clone remote server private project', 'git-clone-remote-server-private-project', 'git-clone-remote-server-private-project', '<p>git clone https://GITHUB_USERNAME:token@github.com/GITHUB_USERNAME/repo_name.git</p>', '<p>git clone https://GITHUB_USERNAME:token@github.com/GITHUB_USERNAME/repo_name.git</p>', 12, 0, '2025-01-19 09:30:52', '2025-01-19 09:30:52'),
(204, 'Mail köçürmə (imapsync Windows Portable)', 'Mail köçürmə (imapsync Windows Portable)', 'mail-kocurme-imapsync-windows-portable', 'mail-kocurme-imapsync-windows-portable', '<p>&nbsp;&nbsp;</p>\n\n<ol>\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><a href=\"https://imapsync.lamiral.info/dist/\">https://imapsync.lamiral.info/dist/</a></span></span></li>\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><a href=\"https://imapsync.lamiral.info/dist/imapsync_2.314.zip\"><span style=\"font-size:13.5pt\">imapsync_2.314.zip</span></a> download</span></span></li>\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\">imapsync.exe run edirik</span></span></li>\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\">run_sync.bat faylını yaradırq i&ccedil;ərisinə aşağıdakını yazırıq</span></span></li>\n</ol>\n\n<pre>\n<code class=\"language-bash\">@echo off\n:: -----------------------------------------------------------\n::   IMAPSYNC - Hostinger → HostGator Email Transfer Script\n::   Prepared by: Rahim (numune.az)\n::   Version: 1.0\n:: -----------------------------------------------------------\n\n:: Switch to the directory of this script\ncd /d \"%~dp0\"\n\n:: -----------------------------------------------------------\n::   Connection Settings\n:: -----------------------------------------------------------\n\nset HOST1=imap.hostinger.com\nset USER1=rahim@numune.az\nset PASS1=old_password\n\nset HOST2=mr2.websitewelcome.com\nset USER2=rahim@numune.az\nset PASS2=new_password\n\n:: -----------------------------------------------------------\n::   Start IMAP Sync\n:: -----------------------------------------------------------\n\necho.\necho ===========================================================\necho            STARTING IMAPSYNC (Hostinger → HostGator)\necho ===========================================================\necho.\n\nimapsync.exe ^\n --host1 %HOST1% --user1 %USER1% --password1 \"%PASS1%\" ^\n --host2 %HOST2% --user2 %USER2% --password2 \"%PASS2%\" ^\n --ssl1 --ssl2\n\necho.\necho ===========================================================\necho                     SYNC FINISHED\necho ===========================================================\necho.\n\npause\n</code></pre>', '<p>&nbsp;&nbsp;</p>\n\n<ol>\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><a href=\"https://imapsync.lamiral.info/dist/\">https://imapsync.lamiral.info/dist/</a></span></span></li>\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\"><a href=\"https://imapsync.lamiral.info/dist/imapsync_2.314.zip\"><span style=\"font-size:13.5pt\">imapsync_2.314.zip</span></a> download</span></span></li>\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\">imapsync.exe run edirik</span></span></li>\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,sans-serif\">run_sync.bat faylını yaradırq i&ccedil;ərisinə aşağıdakını yazırıq</span></span></li>\n</ol>\n\n<pre>\n<code class=\"language-bash\">@echo off\n:: -----------------------------------------------------------\n::   IMAPSYNC - Hostinger → HostGator Email Transfer Script\n::   Prepared by: Rahim (numune.az)\n::   Version: 1.0\n:: -----------------------------------------------------------\n\n:: Switch to the directory of this script\ncd /d \"%~dp0\"\n\n:: -----------------------------------------------------------\n::   Connection Settings\n:: -----------------------------------------------------------\n\nset HOST1=imap.hostinger.com\nset USER1=rahim@numune.az\nset PASS1=old_password\n\nset HOST2=mr2.websitewelcome.com\nset USER2=rahim@numune.az\nset PASS2=new_password\n\n:: -----------------------------------------------------------\n::   Start IMAP Sync\n:: -----------------------------------------------------------\n\necho.\necho ===========================================================\necho            STARTING IMAPSYNC (Hostinger → HostGator)\necho ===========================================================\necho.\n\nimapsync.exe ^\n --host1 %HOST1% --user1 %USER1% --password1 \"%PASS1%\" ^\n --host2 %HOST2% --user2 %USER2% --password2 \"%PASS2%\" ^\n --ssl1 --ssl2\n\necho.\necho ===========================================================\necho                     SYNC FINISHED\necho ===========================================================\necho.\n\npause\n</code></pre>', 11, 0, '2025-12-04 23:26:57', '2025-12-04 23:30:47');
